/*Write a Java program to check if two numbers are anagrams or not. 
If Anagram Number print "Yes" else print "No".

Description: A number is said to be an anagram of some other number 
if it can be made equal to the other number by just shuffling the digits in it.

Sample 1:
input=123
321
output=Yes

Sample 2:
input=121
113
output=No
*/
import java.util.Scanner;
class Anagram 
{ 
	static void updateFreq(int n, int freq[]) 
	{
		while (n > 0) 
		{ 
			int digit = n % 10;  
			freq[digit]++;
			n /= 10; 
		} 
	}  
	static boolean areAnagrams(int a, int b) 
	{
		int [] freqA = new int[10]; 
		int [] freqB = new int[10]; 

		updateFreq(a, freqA);
		updateFreq(b, freqB); 
		for (int i = 0; i < 10; i++) 
		{
			if (freqA[i] != freqB[i]) 
				return false; 
		} 
		return true; 
	} 
	public static void main (String[] args) 
	{ 
		Scanner sc = new Scanner(System.in);
		int a = sc.nextInt(), b = sc.nextInt(); 

		if (areAnagrams(a, b)) 
			System.out.println("Yes"); 
		else
			System.out.println("No"); 
	} 
}

