import java.util.Scanner;
public class Small_Large 
{ 
	static int largest(int num) 
	{
		int[] freq = new int[10]; 
        // count frequency of each digit in the number 
        while (num > 0) 
        { 
            int d = num % 10; 
            freq[d]++; 
            num = num / 10; 
        }
		int result=0;
		for (int i = 9 ; i >= 0 ; i--)
		{			
            while (freq[i] != 0)
			{				
                result = result * 10 + i; 
				freq[i]--;
			}
		}
		return result;
	} 
	static int smallest(int num) 
    { 
        int[] freq = new int[10]; 
        while (num > 0) 
        { 
            int d = num % 10; 
            freq[d]++; 
            num = num / 10; 
        }
        // Set the LEFTMOST digit to minimum expect 0 
        int result = 0; 
        for (int i = 1 ; i <= 9 ; i++) 
        { 
            if (freq[i] != 0) 
            { 
                result = i; 
                freq[i]--; 
                break; 
            } 
        } 
        for (int i = 0 ; i <= 9 ; i++)
		{			
            while (freq[i] != 0)
			{				
                result = result * 10 + i; 
				freq[i]--;
			}
		}
        return result; 
    } 
    public static void main(String args[]) 
    {
		Scanner sc=new Scanner(System.in);
        int num = sc.nextInt();
		System.out.println(smallest(num));		
		System.out.println(largest(num)); 

	} 
}

