import java.util.*;
class BinaryTreeNode
{
	public int data; 
	public BinaryTreeNode left, right; 
	public BinaryTreeNode(int data)
	{
		this.data = data; 
		left = null; 
		right = null; 
	}
}

public class AverageOfLevels
{
	static BinaryTreeNode root;
	void insert(BinaryTreeNode temp, int key)
    {

        if (temp == null) 
		{
            root = new BinaryTreeNode(key);
            return;
        }
        Queue<BinaryTreeNode> q = new LinkedList<BinaryTreeNode>();
        q.add(temp);

        // Do level order traversal until we find
        // an empty place.
        while (!q.isEmpty()) 
		{
            temp = q.peek();
            q.remove();

            if (temp.left == null) 
			{
                temp.left = new BinaryTreeNode(key);
                break;
            }
            else
                q.add(temp.left);

            if (temp.right == null) 
			{
                temp.right = new BinaryTreeNode(key);
                break;
            }
            else
                q.add(temp.right);
        }
    }
	public List<Double> averageOfLevels(BinaryTreeNode root) 
	{
      if(root == null)
        return null;
      List<Double> result = new ArrayList<>();
      Queue<BinaryTreeNode> q = new LinkedList<>();
      q.offer(root);
      while(!q.isEmpty())
	  {
        int sum = 0;
        int t = q.size(); // no of nodes in level
         for(int i=0;i<t;i++)
		 {
          BinaryTreeNode n = q.poll();
          sum +=n.data;
          if(n.left != null&&n.left.data!=-1)
            q.offer(n.left);
          if(n.right != null&&n.right.data!=-1)
            q.offer(n.right);
        }
        result.add(sum * 1.0 / t);
      }
      return result;
    }
	public static void main(String[] args) 
	{
		Scanner sc=new Scanner(System.in);
		String str[]=sc.nextLine().split(" ");
		AverageOfLevels st=new AverageOfLevels();
		root=new BinaryTreeNode(Integer.parseInt(str[0]));
		for(int i=1; i<str.length; i++)
			st.insert(root,Integer.parseInt(str[i]));
		System.out.println(st.averageOfLevels(root));	
	}
}

import java.util.*;
class BalancedStringsSplit 
{
    public static int balancedStringSplit(String s) 
	{
        if(s.length() == 0)
          return 0;

        int n=0,g=0;
        int ct = 0;
        for(int i=0;i<s.length();i++)
		{
            if(s.charAt(i) == 'N')
			{
                n++;
            }
            else if(s.charAt(i) == 'G')
			{
                g++;
            }
            if(n == g)
			{
                ct++;                  
            }
        }
        return ct;

    }
	public static void main(String[] args) 
	{
		Scanner s=new Scanner(System.in);
		String str=s.next();
		System.out.println(balancedStringSplit(str));
	}
}

