import java.util.*;

public class CipherPasswordGenerator 
{
    public static void main(String[] args)
	{
        Scanner s = new Scanner(System.in);

        // Read input: question paper name and secret key
        String P = s.nextLine();
        int K = s.nextInt();

        StringBuilder result = new StringBuilder();

        for (char ch : P.toCharArray()) 
		{
            // Check if character is a lowercase letter
            if (ch >= 'a' && ch <= 'z') 
			{
                int shifted = ch + K;

                // Wrap around if out of range [65, 126]
                while (shifted > 126) 
				{
                    shifted = 65 + (shifted - 127);
                }
                while (shifted < 65) 
				{
                    shifted = 126 - (64 - shifted);
                }

                result.append((char) shifted);
            } 
			else 
			{
                // Retain character as it is (uppercase, number, space, special)
                result.append(ch);
            }
        }

        // Output the final password
        System.out.println(result.toString());
    }
}

