import java.util.*;
class  CountComponents
{
    static int[] p;
    static int find(int x)
	{ 
		while(p[x]>=0)
			x=p[x];
		return x;
	}
    static void union(int a,int b)
	{
        int ra=find(a);
	    int rb=find(b);
        if(ra==rb) 
			return;
        p[ra]=rb;
	}

    public static int components(int[][] g) 
	{
        int R = g.length, C = g[0].length;
        p = new int[R*C]; 
		for(int i=0;i<R*C;i++)
		{
				p[i]=-1;
		}
        //int ones = 0;
        int[][] dirs = { {1,0},{0,1} };

        for (int r=0;r<R;r++)
		{
            for (int c=0;c<C;c++)
			{
                if (g[r][c]==1)
				{
                   // ones++;
                    int id = r*C + c;
                    for (int[] dxy:dirs) 
					{
                        int nr=r+dxy[0], nc=c+dxy[1];
                        if (nr<R && nc<C && g[nr][nc]==1) 
						{
                           union(id, nr*C+nc);
                        }
                    }
                }
			}
		}
        Set<Integer> roots = new HashSet<>();
        for (int r=0;r<R;r++)
            for (int c=0;c<C;c++)
                if (g[r][c]==1) 
					roots.add(find(r*C+c));
        return roots.size();
    }

    public static void main(String[] args)
	{
		Scanner sc=new Scanner(System.in);
		int R=sc.nextInt();
		int C=sc.nextInt();
		int grid[][]=new int[R][C];
		for(int i=0;i<R;i++)
			for(int j=0;j<C;j++)
				grid[i][j]=sc.nextInt();
        System.out.println(components(grid)); // 3
    }
}

