import java.util.*;

class  GroupWords
{
    static int[] p;
    static int find(int x)
	{ 
		while(p[x]>=0)
			x=p[x];
		return x;
	}
    static void union(int a,int b)
	{
        int ra=find(a);
	    int rb=find(b);
        if(ra==rb) 
			return;
        p[ra]=rb;
	}


    /* returns number of anagram groups */
    public static int groupCount(String[] words) 
	{
        int n = words.length;
        p = new int[n]; 
		for(int i=0;i<n;i++)
		{
				p[i]=-1;
		}

        Map<String,Integer> map = new HashMap<>();
        for (int i=0;i<n;i++) 
		{
            char[] ch = words[i].toCharArray();
            Arrays.sort(ch);
            String key = new String(ch);
            if (!map.containsKey(key))
				map.put(key,i);
            else union(i, map.get(key));
        }

        Set<Integer> roots = new HashSet<>();
        for (int i=0;i<n;i++) 
			roots.add(find(i));
        return roots.size();
    }

    public static void main(String[] args) 
	{
        Scanner sc=new Scanner(System.in);
		int n=sc.nextInt();
        String[] words = new String[n];
		for(int i=0;i<n;i++)
		{
			words[i]=sc.next();
		}
        System.out.println(groupCount(words)); 
    }
}

