import java.util.*;

class BinaryTreeNode{
	public int data; 
	public BinaryTreeNode left, right; 
	public BinaryTreeNode(int data)
	{
		this.data = data; 
		left = null; 
		right = null; 
	}
}
public class IncreasingBST
{
	static BinaryTreeNode root;
	void insert(BinaryTreeNode temp, int key)
    {
         if (temp == null) 
		{
            root = new BinaryTreeNode(key);
            return;
        }
        Queue<BinaryTreeNode> q = new LinkedList<BinaryTreeNode>();
        q.add(temp);

        // Do level order traversal until we find an empty place.
        while (!q.isEmpty()) 
		{
            temp = q.peek();
            q.remove();

            if (temp.left == null) 
			{
                temp.left = new BinaryTreeNode(key);
                break;
            }
            else
                q.add(temp.left);

            if (temp.right == null) 
			{
                temp.right = new BinaryTreeNode(key);
                break;
            }
            else
                q.add(temp.right);
        }
    }
	// Main function
    public static BinaryTreeNode increasingBST(BinaryTreeNode root) 
	{
        ArrayList<BinaryTreeNode> ans = new ArrayList<>();
        inorder(ans, root);
		return tree(ans, 0);
    }

    // Inorder traversal to collect nodes
    public static void inorder(ArrayList<BinaryTreeNode> ans, BinaryTreeNode root) 
	{
        if (root == null||root.data==-1) return;
        inorder(ans, root.left);
        ans.add(root);
        inorder(ans, root.right);
    }

    // Build the new right-skewed tree
    public static BinaryTreeNode tree(ArrayList<BinaryTreeNode> ans, int i) 
	{
        if (i == ans.size())
			return null;
		BinaryTreeNode node = ans.get(i);
        node.left = null;
        node.right=tree(ans, i + 1);
		return node;
    }

    // Print the right-skewed tree
    private static void printRightSkewed(BinaryTreeNode root) 
	{
        while (root != null) {
            System.out.print(root.data + " ");
            root = root.right;
        }
        System.out.println();
    }
    public static void main(String[] args) 
	{
        Scanner sc=new Scanner(System.in);
		String str[]=sc.nextLine().split(" ");
		IncreasingBST st=new IncreasingBST();
		root=new BinaryTreeNode(Integer.parseInt(str[0]));
		for(int i=1; i<str.length; i++)
			st.insert(root,Integer.parseInt(str[i]));
		root=increasingBST(root);
		printRightSkewed(root);
    }
}
