import java.util.*;

public class LargestComponentByCommonFactor {

    static class DSU {
        int[] p, sz;
        DSU(int n){ p=new int[n]; sz=new int[n]; for(int i=0;i<n;i++){p[i]=i; sz[i]=1;} }
        int find(int x){ return p[x]==x? x : (p[x]=find(p[x])); }
        void union(int a,int b){
            int ra=find(a), rb=find(b);
            if(ra==rb) return;
            if(sz[ra]<sz[rb]){ p[ra]=rb; sz[rb]+=sz[ra]; }
            else { p[rb]=ra; sz[ra]+=sz[rb]; }
        }
        int size(int x){ return sz[find(x)]; }
    }

    /** Returns size of the largest component where numbers share a common factor > 1. */
    public static int largestComponentSize(int[] nums) {
        int n = nums.length;
        DSU dsu = new DSU(n);
        Map<Integer, Integer> factorToIdx = new HashMap<>();

        for (int i = 0; i < n; i++) {
            int x = nums[i];
            // factorize x
            for (int f = 2; f * f <= x; f++) {
                if (x % f == 0) {
                    // union current index with previous index sharing this factor
                    connectFactor(f, i, factorToIdx, dsu);
                    while (x % f == 0) x /= f;
                }
            }
            if (x > 1) connectFactor(x, i, factorToIdx, dsu); // remaining prime factor
        }

        int best = 0;
        for (int i = 0; i < n; i++)
            best = Math.max(best, dsu.size(i));
        return best;
    }

    private static void connectFactor(int factor, int idx,
                                      Map<Integer,Integer> mp, DSU dsu) {
        if (!mp.containsKey(factor)) mp.put(factor, idx);
        else dsu.union(idx, mp.get(factor));
    }

    public static void main(String[] args) {
        int[] nums = {4,6,15,35};
        System.out.println("Largest component size = "
                + largestComponentSize(nums)); //  4
    }
}

