public class LargestValues
{
	static BinaryTreeNode root;
	void insert(BinaryTreeNode temp, int key)
    {

        if (temp == null) 
		{
            root = new BinaryTreeNode(key);
            return;
        }
        Queue<BinaryTreeNode> q = new LinkedList<BinaryTreeNode>();
        q.add(temp);

        // Do level order traversal until we find
        // an empty place.
        while (!q.isEmpty()) 
		{
            temp = q.peek();
            q.remove();

            if (temp.left == null) 
			{
                temp.left = new BinaryTreeNode(key);
                break;
            }
            else
                q.add(temp.left);

            if (temp.right == null) 
			{
                temp.right = new BinaryTreeNode(key);
                break;
            }
            else
                q.add(temp.right);
        }
    }
	List<Integer> largestValues(BinaryTreeNode root)
    {
        List<Integer> l = new ArrayList<>();
        if(root == null)
            return l;

        Queue<BinaryTreeNode> q = new LinkedList<>();
        q.offer(root);

        while(!q.isEmpty())
        {
            int size = q.size();
            int max = Integer.MIN_VALUE;
            for(int i=0;i<size;i++)
            {
                BinaryTreeNode p = q.poll();
                if(p.left!= null)
                    q.offer(p.left);
                if(p.right!= null)
                    q.offer(p.right);
                max = Math.max(max,p.data);   //Storing the max of each row...
            }
            l.add(max);
        }
        return l;
    }
	public static void main(String[] args) 
	{
		Scanner sc=new Scanner(System.in);
		String str[]=sc.nextLine().split(" ");
		LargestValues st=new LargestValues();
		root=new BinaryTreeNode(Integer.parseInt(str[0]));
		for(int i=1; i<str.length; i++)
			st.insert(root,Integer.parseInt(str[i]));
		System.out.println(st.largestValues(root));	
	}
}

