class MinDifference 
{
    static int ans = Integer.MAX_VALUE;
    static BinaryTreeNode pre = null;
	static BinaryTreeNode root;
	void insert(BinaryTreeNode temp, int key)
    {
         if (temp == null) 
		{
            root = new BinaryTreeNode(key);
            return;
        }
        Queue<BinaryTreeNode> q = new LinkedList<BinaryTreeNode>();
        q.add(temp);

        // Do level order traversal until we find an empty place.
        while (!q.isEmpty()) 
		{
            temp = q.peek();
            q.remove();

            if (temp.left == null) 
			{
                temp.left = new BinaryTreeNode(key);
                break;
            }
            else
                q.add(temp.left);

            if (temp.right == null) 
			{
                temp.right = new BinaryTreeNode(key);
                break;
            }
            else
                q.add(temp.right);
        }
    }

    public static int minDiffInBST(BinaryTreeNode root) 
	{
        inOrder(root);
        return ans;
    }

    private static void inOrder(BinaryTreeNode root) {
        if (root == null||root.data==-1) return;
        inOrder(root.left);
        if (pre != null) 
		{
            ans = Math.min(ans, root.data - pre.data);
        }
        pre = root;
        inOrder(root.right);
    }
	public static void main(String[] args) 
	{
        Scanner sc=new Scanner(System.in);
		String str[]=sc.nextLine().split(" ");
		MinDifference st=new MinDifference();
		root=new BinaryTreeNode(Integer.parseInt(str[0]));
		for(int i=1; i<str.length; i++)
			st.insert(root,Integer.parseInt(str[i]));
        int result = minDiffInBST(root);
        System.out.println(result);
    }
}
