/*
You are given an integer array coins representing coins of different 
denominations and an integer amount representing a total amount of money.
Write a java program using dynamic programming memoization approach
to return the fewest number of coins that you need to make up that amount.
If that amount of money cannot be made up by any combination of the coins, 
return -1.

You may assume that you have an infinite number of each kind of coin.



Example 1:

Input: coins = [1,2,5], amount = 11
Output: 3
Explanation: 11 = 5 + 5 + 1
Example 2:

Input: coins = [2], amount = 3
Output: -1
Example 3:

Input: coins = [1], amount = 0
Output: 0
*/
import java.util.*;
class CoinChange2 
{
	public static int coinChange(int[] coins, int amount) 
	{
        int[] dp = new int[amount + 1];
        coinChange(coins, amount, dp);
        return dp[amount] == dp.length ? -1 : dp[amount];
    }
    public static int coinChange(int[] coins, int amount, int[] dp) 
	{
        if (amount == 0) 
		{
            return 0;
        }
        if (dp[amount] != 0) 
		{
            return dp[amount];
        }
        dp[amount] = dp.length;
        for (int coin : coins) 
		{
            if (amount >= coin) 
			{
                dp[amount] = Math.min(dp[amount], coinChange(coins, amount - coin, dp) + 1);
            }
        }
        return dp[amount];
    }
	public static void main(String[] args) 
	{
		Scanner s=new Scanner(System.in);
		int n=s.nextInt();
		int coins[]=new int[n];
		for(int i=0;i<n;i++)
			coins[i]=s.nextInt();
		int amount=s.nextInt();
		System.out.println(coinChange(coins,amount));
	}
}

