        int n=sc.nextInt();
        System.out.println(distinctIntegers(n));
    }
}

/*
Given a string s, return the number of substrings that have only 
one distinct letter.


Example 1:
Input: s = "aaaba"
Output: 8

Explanation: The substrings with one distinct letter are "aaa", "aa", "a", "b".
"aaa" occurs 1 time.
"aa" occurs 2 times.
"a" occurs 4 times.
"b" occurs 1 time.
So the answer is 1 + 2 + 4 + 1 = 8.

Example 2:
Input: s = "aaaaaaaaaa"
Output: 55
*/
import java.util.*;

class CountSubstrings1 
{
    public static int countLetters(String s) 
	{
		int i=0,j=0,ct=0;
		int n=s.length();
		while(i<n&j<n)
		{
			while((j+1<n)&&s.charAt(j)==s.charAt(j+1))
				j++;

			int len = j - i + 1;
			ct += (len * (len + 1)) / 2;  //(n*(n+1))/2

			i=j+1;
			j=i;
		}
		return ct;
    }

	public static void main(String args[])
	{
		Scanner sc=new Scanner(System.in);
		String s=sc.next();
		System.out.println(countLetters(s));
	}
}

