import java.util.*;
class FormSmallestNumberFromTwoDigitArrays
 {
    public static int minNumber(int[] nums1, int[] nums2) 
    {
        int ans=0;

        Arrays.sort(nums1);
        Arrays.sort(nums2);

        HashSet<Integer> set = new HashSet<>();
        for(int i:nums2)
        {
            set.add(i);
        }

        for(int i:nums1)
        {
            if(set.contains(i)) return i;
        }

        ans = nums1[0]*10 + nums2[0];
        int ans2 = nums2[0]*10 + nums1[0];

        return Math.min(ans,ans2);
    }

    public static void main(String args[])
    {
        Scanner sc=new Scanner(System.in);
        int n1=sc.nextInt();

       int a[]=new int[n1];
       for(int i=0;i<n1;i++)
