import java.util.*;
// Greedy approach
public class Knapsack 
{
	// item value class
	static class ItemValue 
	{
		int value, weight;
		// item value function
		public ItemValue(int val, int wt)
		{
			this.weight = wt;
			this.value = val;
		}
	}

	// function to get maximum value
	private static double getMaxValue(ItemValue[] arr, int capacity)
	{
		// sorting items by value/weight ratio;
		Arrays.sort(arr, new Comparator<ItemValue>() 
		{
			public int compare(ItemValue item1, ItemValue item2)
			{
				double cpr1 = ((double)item1.value / (double)item1.weight);
				double cpr2 = ((double)item2.value / (double)item2.weight);
				if (cpr1 < cpr2)
					return 1;
				else
					return -1;
			}
		});
		double totalValue = 0d;
		for (ItemValue i : arr) 
		{
			int curWt = (int)i.weight;
			int curVal = (int)i.value;
			if (capacity - curWt >= 0) {

				// this weight can be picked while
				capacity = capacity - curWt;
				totalValue += curVal;
			}
			else 
			{
				// item cant be picked whole
				double fraction= ((double)capacity / (double)curWt);
				totalValue += (curVal * fraction);
				capacity = (int)(capacity - (curWt * fraction));
				break;
			}
		}
		return totalValue;
	}

	// Driver's code
	public static void main(String args[])
	{
		Scanner sc=new Scanner(System.in);
		int size = sc.nextInt();
		int capacity = sc.nextInt();

		ItemValue arr[] = new ItemValue[size];
		for(int i=0;i<size;i++)
			arr[i] = new ItemValue(sc.nextInt(), sc.nextInt());
		double maxValue = getMaxValue(arr, capacity);
		System.out.println(maxValue);
	}
}
