import java.util.*;
class  MaxApples
{
	public static int maxNumberOfApples(int[] weights) 
	{
        Arrays.sort(weights);

        int totalWeight = 0;
        int unit = 0;
        for (int appleWeight : weights) 
		{
            totalWeight += appleWeight;

            if (totalWeight > 5000) 
			{
                break;
            }
            unit++;
        }

        return unit;

    }
	public static void main(String[] args) 
	{
