/*
Minimum product subset of an array
The minimum product subset of an array refers to a subset of elements from the array such that the 
product of the elements in the subset is minimized.


One common algorithm used to find the minimum product subset of an array is the greedy algorithm. 
The basic idea of this algorithm is to start with the first element of the array and add the next element 
to the subset only if it will result in a smaller product. The advantage of this algorithm is its simplicity and
ease of implementation. However, the greedy algorithm may not always produce the optimal solution 
and can be very slow for large arrays.

A better solution is to use the below facts.  

If there are even number of negative numbers and no zeros, the result is the product of all except the 
largest valued negative number.
If there are an odd number of negative numbers and no zeros, the result is simply the product of all.
If there are zeros and positive, no negative, the result is 0. The exceptional case is when there is no 
negative number and all other elements positive then our result should be the first minimum positive
number.

Input : 
5
-1 -1 -2 4 3
Output : -24
Explanation : Minimum product will be ( -2 * -1 * -1 * 4 * 3 ) = -24

Input :
2
-1 0
Output : -1
Explanation : -1(single element) is minimum product possible

Input : 
3
0 0 0
Output : 0
*/
import java.util.*;
class MinProductSubset
{
    static int minProductSubset(int a[], int n)
    {
        if (n == 1)
            return a[0];

        // Find count of negative numbers, count of zeros, maximum valued negative number, 
		// minimum valued positive number and product of non-zero numbers

        int negmax = Integer.MIN_VALUE;
        int posmin = Integer.MAX_VALUE;
        int count_neg = 0, count_zero = 0;
        int product = 1;

        for (int i = 0; i < n; i++) 
		{
            // if number is zero,count it but dont multiply
            if (a[i] == 0)
			{
                count_zero++;
                continue;
            }
            // count the negative numbers and find the max negative number
            if (a[i] < 0) 
			{
                count_neg++;
                negmax = Math.max(negmax, a[i]);
            }

            // find the minimum positive number
            if (a[i] > 0 && a[i] < posmin)
                posmin = a[i];

            product *= a[i];
        }

        // if there are all zeroes or zero is present but no negative number is present
        if (count_zero == n || (count_neg == 0 && count_zero > 0))
            return 0;

        // If there are all positive
        if (count_neg == 0)
            return posmin;

        // If there are even number except zero of negative numbers
        if (count_neg % 2 == 0 && count_neg != 0) 
		{
            // Otherwise result is product of all non-zeros divided by maximum valued negative.
            product = product / negmax;
        }

        return product;
    }

    // main function
    public static void main(String[] args)
    {
        Scanner sc=new Scanner(System.in);
		int n=sc.nextInt();
		int a[]=new int[n];
		for(int i=0;i<n;i++)
			a[i]=sc.nextInt();
        System.out.println(minProductSubset(a, n));
    }
}
