import java.util.*;
class  PathsWithObstacle
{
    public static int uniquePathsWithObstacles(int o[][]) 
	{
        int R = o.length;
        int C = o[0].length;

        // If the starting cell has an obstacle, then simply return as there 
		// would be no paths to the destination.
        if (o[0][0] == 1) 
		{
            return 0;
        }

        // Number of ways of reaching the starting cell = 1.
        o[0][0] = 1;

        // Filling the values for the first column
        for (int i = 1; i < R; i++) 
		{
            o[i][0] = (o[i][0] == 0 && o[i - 1][0] == 1)?1:0;
        }

