/*
1122. Relative Sort Array
Given two arrays arr1 and arr2, the elements of arr2 are distinct, and all elements in arr2 are also in arr1.

Sort the elements of arr1 such that the relative ordering of items in arr1 are the same as in arr2. 
Elements that do not appear in arr2 should be placed at the end of arr1 in ascending order.

Example 1:

Input: 
11
2 3 1 3 2 4 6 7 9 2 19
6
2 1 4 3 9 6
Output: [2, 2, 2, 1, 4, 3, 3, 9, 6, 7, 19]
Example 2:

Input: 
6
28 6 22 8 44 17
4
22 28 8 6
Output: [22, 28, 8, 6, 17, 44]
*/
import java.util.*;
class  RelativeSort
{
    public static int[] relativeSortArray(int[] arr1, int[] arr2) 
	{
        // Step 1: Create a count array to store the count of each element in arr1
        int[] cnt = new int[1001];
        for (int i : arr1) 
		{
            cnt[i]++;
        }

        // Step 2: Create a result array to store the final sorted elements
        int[] ans = new int[arr1.length];
        int i = 0;

        // Step 3: Place elements of arr2 into the result array
        for (int n : arr2) 
		{
            while (cnt[n] > 0) 
			{
                ans[i] = n;
                cnt[n]--;
                i++;
            }
        }

        // Step 4: Place remaining elements in ascending order
        for (int j = 0; j < cnt.length; j++) 
		{
            while (cnt[j] > 0) 
			{
                ans[i] = j;
                cnt[j]--;
                i++;
            }
        }

        // Return the result array
        return ans;
    }
	public static void main(String[] args) 
	{
		Scanner sc=new Scanner(System.in);
		int m=sc.nextInt();
		int a1[]=new int[m];
		for(int i=0;i<m;i++)
			a1[i]=sc.nextInt();
		int n=sc.nextInt();
		int a2[]=new int[n];
		for(int i=0;i<n;i++)
			a2[i]=sc.nextInt();
		System.out.println(Arrays.toString(relativeSortArray(a1, a2)));
	}
}

