import java.util.*;

public class TopologicalSort 
{
    static int V; // number of vertices
    static int[][] adjMatrix; // adjacency matrix
    private Stack<Integer> stack; // stack for storing sorted vertices

    public TopologicalSort(int V) 
	{
        this.V = V;
        adjMatrix = new int[V][V];
        stack = new Stack<>();
    }

    public void addEdge(int i, int j) 
	{
        adjMatrix[i][j] = 1;
    }

    public void topologicalSort() 
	{
        boolean[] visited = new boolean[V];
        for (int i = 0; i < V; i++) 
		{
            visited[i] = false;
        }

        for (int i = 0; i < V; i++) 
		{
            if (!visited[i]) 
			{
                topologicalSortUtil(i, visited);
            }
        }

        System.out.println("Topological sorting order:");
        while (!stack.isEmpty()) {
            System.out.print(stack.pop() + " ");
        }
    }

    private void topologicalSortUtil(int v, boolean[] visited)
	{
        visited[v] = true;

        for (int i = 0; i < V; i++) 
		{
            if (adjMatrix[v][i] == 1 && !visited[i]) 
			{
                topologicalSortUtil(i, visited);
            }
        }

        stack.push(v);
    }

    public static void main(String[] args) 
	{
		Scanner s=new Scanner(System.in);
		V=s.nextInt();
		TopologicalSort g = new TopologicalSort(V);
		int E=s.nextInt();
		for(int i=1;i<=E;i++)
		{
			int u=s.nextInt();
			int v=s.nextInt();
			g.addEdge(u,v);
		}
        g.topologicalSort();
    }
}


/*Topological sorting is a sorting algorithm that is used to sort a directed acyclic graph (DAG) in a linear order, 
such that for every directed edge (u, v) from vertex u to vertex v, u comes before v in the ordering.

In other words, topological sorting produces a sequence of vertices such that every vertex appears before all of its 
successors in the DAG.

Topological sorting has a wide range of applications in computer science, such as task scheduling, job sequencing, 
and dependency resolution. For example, in a project management tool, the dependencies between tasks can be modeled 
as a DAG, and topological sorting can be used to schedule the tasks in the correct order.

The algorithm for topological sorting involves iterating over all the vertices in the graph, and visiting each vertex only once. 
For each unvisited vertex, we perform a depth-first search (DFS) on its adjacent vertices. Once all adjacent vertices have been
visited, we add the current vertex to a stack. When all vertices have been visited, the top of the stack represents the first vertex
