/*
A construction company is managing the workflow of building a multi-storey office complex.
Certain tasks must be completed before others can begin, due to dependency and safety 
requirements.
This can be modeled as a Directed Acyclic Graph (DAG) where:
Each task is a node.
An edge from task A to task B means A must be completed before B starts.
To determine the proper order in which the construction tasks should be performed, the 
project manager uses Topological Sorting(USE DFS).

Example Tasks and Dependencies

Lay foundation
Build ground floor structure (depends on: Lay foundation)
Build upper floors (depends on: Ground floor structure)
Install electrical wiring (depends on: Ground floor structure)
Install plumbing (depends on: Ground floor structure)
Paint walls (depends on: Electrical wiring and Plumbing)
Install interior fixtures (depends on: Paint walls)
Final inspection (depends on: Install interior fixtures)

Sample Input and Output:
8  (number of vertices)
8  (number of edges)
1  2
2  3
2  4
2  5
4  6
5  6
6  7
7  8
Topological Sort :
1  2  5  4  6  7  8  3
*/

import java.util.*;

public class TopologicalSortDFS 
{
    static int V; // number of vertices
    static int[][] adjMatrix; // adjacency matrix
    private Stack<Integer> stack; // stack for storing sorted vertices

    public TopologicalSortDFS(int V) 
	{
        this.V = V;
        adjMatrix = new int[V+1][V+1];
        stack = new Stack<>();
    }

    public void addEdge(int i, int j) 
	{
        adjMatrix[i][j] = 1;
    }

    public void topologicalSort() 
	{
        boolean[] visited = new boolean[V+1];
        for (int i = 1; i <=V; i++) 
		{
            visited[i] = false;
        }

        for (int i = 1; i <=V; i++) 
		{
            if (!visited[i]) 
			{
                topologicalSortUtil(i, visited);
            }
        }

        while (!stack.isEmpty()) 
		{
            System.out.print(stack.pop() + " ");
        }
    }

    private void topologicalSortUtil(int v, boolean[] visited)
	{
        visited[v] = true;

        for (int i = 1; i <=V; i++) 
		{
            if (adjMatrix[v][i] == 1 && !visited[i]) 
			{
                topologicalSortUtil(i, visited);
            }
        }

        stack.push(v);
    }

    public static void main(String[] args) 
	{
		Scanner s=new Scanner(System.in);
		V=s.nextInt();
		TopologicalSortDFS g = new TopologicalSortDFS(V);
		int E=s.nextInt();
		for(int i=1;i<=E;i++)
		{
			int u=s.nextInt();
			int v=s.nextInt();
			g.addEdge(u,v);
		}
        g.topologicalSort();
    }
}

