import java.util.*;
class TriboNumber1 
{
	public static int tribonacci(int n) 
	{
        if (n < 4) 
		{
            return n > 1 ? 1 : 0;
        }

        int[] dp = new int[n + 1];
        dp[1] = 0;
        dp[2] = 1;
		dp[3] = 1;

        for (int i = 4; i <= n; ++i) 
		{
            dp[i] = dp[i - 1] + dp[i - 2] + dp[i - 3];
        }

        return dp[n];
    }
	public static void main(String[] args) 
	{
		Scanner s=new Scanner(System.in);
		int n=s.nextInt();
		System.out.println(tribonacci(n));
	}
}

