import java.util.*;
class  TriboNumber2
{
	public static int tribonacci(int n) 
	{
        int[] dp = new int[n+1];
        Arrays.fill(dp,-1);
        return findTrib(n,dp);
    }
    public static int findTrib(int n,int[] dp)
    {
        if(n == 1)
		{
            return 0;
        }
        if(n==2 || n==3)
		{
            return 1;
        }

        if(dp[n] != -1)
		{
            return dp[n];
        }

        return dp[n] = findTrib(n-3,dp)+findTrib(n-2,dp)+findTrib(n-1,dp);
    } 
	public static void main(String[] args) 
	{
		Scanner s=new Scanner(System.in);
		int n=s.nextInt();
		System.out.println(tribonacci(n));
	}
}

