import java.util.*;
class UniquePaths2 
{
	  public static int uniquePaths(int m, int n) 
	  {
        return path(m - 1, n - 1, new int[m][n]);
      }

	  private static int path(int m, int n, int[][] dp) 
	  {
		if (m < 0 || n < 0) 
		{
		  return 0;
		} 
		else if (m == 0 || n == 0) 
		{
		  return 1;
		} 
		else if (dp[m][n] > 0) 
		{
		  return dp[m][n];
		}
		else
		{
		  dp[m][n] = path(m - 1, n, dp) + path(m, n - 1, dp);
		  return dp[m][n];
		}
	  }
	public static void main(String[] args) 
	{
		Scanner sc = new Scanner(System.in);
		int m=sc.nextInt();
        int n = sc.nextInt();
		System.out.println(uniquePaths(m, n));
	}
}

