/*
You are given an array prices where prices[i] is the price of a given stock on
the ith day.
You want to maximize your profit by choosing a single day to buy one stock
and choosing a different day in the future to sell that stock.
Write a java program to return the maximum profit you can achieve from 
this transaction. If you cannot achieve any profit, return 0.

Example 1:
Input: prices = [7,1,5,3,6,4]
Output: 5
Explanation: Buy on day 2 (price = 1) and sell on day 5 (price = 6),
profit = 6-1 = 5.
Note that buying on day 2 and selling on day 1 is not allowed because 
you must buy before you sell.

Example 2:
Input: prices = [7,6,4,3,1]
Output: 0
Explanation: In this case, no transactions are done and the max profit = 0.
*/
/*  Best Time to Buy and Sell Stock  DP tabulation (one transaction)  */
import java.util.*;

public class BestTime 
{
    // O(n) time, O(n) space (tabulation table)
    public static int maxProfit(int[] prices) 
	{
        int n = prices.length;
        if (n == 0) return 0;

        int[][] dp = new int[n][2];
        dp[0][0] = 0;                 // not holding after day 0
        dp[0][1] = -prices[0];   // holding after buying on day 0

        for (int i = 1; i < n; i++)
		{
            // Either we were already not holding, or we sell today
            dp[i][0] = Math.max(dp[i - 1][0], dp[i - 1][1] + prices[i]);

            // Either we were already holding, or we buy today
            // (buying resets the balance to -prices[i] because only one 
			// buy allowed)
            dp[i][1] = Math.max(dp[i - 1][1], -prices[i]);
        }
        return dp[n - 1][0];   // profit at the end with no stock in hand
    }

    public static void main(String[] args) 
	{
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int[] prices = new int[n];
        for (int i = 0; i < n; i++) 
			prices[i] = sc.nextInt();
        System.out.println(maxProfit(prices));
    }
}


