/*
Given the root of a binary tree with unique values and the values of two 
different nodes of the tree x and y, return true if the nodes corresponding 
to the values x and y in the tree are cousins, or false otherwise.

Two nodes of a binary tree are cousins if they have the same depth with
different parents.

Note that in a binary tree, the root node is at the depth 1, and children 
of each depth k node are at the depth k + 1.


Example 1:
Input: 
1 2 3 4]
4 3

                    1
                    /\
                    2 3
                    /
                    4
Output: false

Example 2:
Input: 
1 2 3 -1 4 -1 5
5 4
Output: true

                    1       -----1
                    /\
                   2  3 --------2
                   /\  /\
                -1   4 -1 5-------3

Example 3:
Input: 
1 2 3 -1 4
2 3
Output: false

*/

import java.util.*;

class BinaryTreeNode{
	public int data; 
	public BinaryTreeNode left, right; 
	public BinaryTreeNode(int data){
		this.data = data; 
		left = null; 
		right = null; 
	}
}

class Cousins
{
	static int depth[],parent[];
	static boolean visited[];
	static BinaryTreeNode root;
	static void insert(BinaryTreeNode temp, int key)
    {

        if (temp == null) 
		{
            root = new BinaryTreeNode(key);
            return;
        }
        Queue<BinaryTreeNode> q = new LinkedList<BinaryTreeNode>();
        q.add(temp);

        // Do level order traversal until we find an empty place.
        while (!q.isEmpty()) 
		{
            temp = q.peek();
            q.remove();

            if (temp.left == null) 
			{
                temp.left = new BinaryTreeNode(key);
                break;
            }
            else
                q.add(temp.left);

            if (temp.right == null) 
			{
                temp.right = new BinaryTreeNode(key);
                break;
            }
            else
                q.add(temp.right);
        }
	}

		public static void dfs(BinaryTreeNode root)
		{
			visited[root.data]=true;
			if(root.left!=null&&root.left.data!=-1)
			{
				depth[root.left.data]=depth[root.data]+1;
				parent[root.left.data]=root.data;
				dfs(root.left);
			}
			if(root.right!=null&&root.right.data!=-1)
			{
				depth[root.right.data]=depth[root.data]+1;
				parent[root.right.data]=root.data;
				dfs(root.right);
			}
		}

		static boolean areCousins(BinaryTreeNode root,BinaryTreeNode u, BinaryTreeNode v)
		{
			return (depth[u.data] == depth[v.data] && parent[u.data] != parent[v.data])? true:false;
		}
    	public static void main(String args[])
		{
			Scanner sc=new Scanner(System.in);
			String str[]=sc.nextLine().split(" ");
			root=new BinaryTreeNode(Integer.parseInt(str[0]));
			for(int i=1 ; i<str.length; i++)
				insert(root,Integer.parseInt(str[i]));
			BinaryTreeNode p=new BinaryTreeNode(sc.nextInt());
			BinaryTreeNode q=new BinaryTreeNode(sc.nextInt());
			depth=new int[100];
			parent=new int[100];
			visited=new boolean[100];
			depth[root.data]=1;
			dfs(root);
			System.out.println(areCousins(root,p,q));
		}
}

