/*
Problem Statement
In a distant future, humans have started communicating with machines 
using a special encrypted code system. 
Each letter from 'A' to 'Z' is mapped to a unique numeric value as follows:

'A' -> 1
'B' -> 2
...

'Z' ->26

You are given a secret message in the form of a string consisting only of 
digits. This message was encoded using the mapping above.

Your task is to write a program that determines how many distinct ways the 
message can be decoded back into a valid sequence of letters.

A digit '0' has no corresponding letter and 
must only appear as part of a valid two-digit code, like '10' or '20'.

You cannot skip or rearrange digits.

Input - A string s containing only digits (1 <= s.length <= 100).
Output - An integer representing the total number of ways to decode the 
given encrypted string.

Input = 12
Output = 2
Explanation: Possible decodings are "AB" (1 2) and "L" (12).

Input = 226
Output = 3
Explanation: Possible decodings are "BZ" (2 26), "VF" (22 6), and 
"BBF" (2 2 6).

Input = 0
Output =  0
Explanation: '0' is invalid unless part of "10" or "20".

Input = 1
Output = 1
Explanation: Only one valid decoding: "A".


//back end test cases

case = 1
input = 1112131415
output = 52

case = 2
input = 1111111111
output = 89

case = 3
input = 123456789101112
output = 15

case = 4
input = 222222222222
output = 233

case = 5
input = 10112625
output = 10

*/
import java.util.*;
class  DecodeWays
{
    public static int numDecodings(String s) 
	{
		int n=s.length();
        // DP array to store the subproblem results
        int[] dp = new int[n + 1];
        dp[0] = 1;

        // Ways to decode a string of size 1 is 1. Unless the string is '0'.
        // '0' doesn't have a single digit decode.
        dp[1] = s.charAt(0) == '0' ? 0 : 1;

        for (int i = 2; i < dp.length; i++) 
		{
            // Check if successful single digit decode is possible.
            int oneDigit = Integer.valueOf(s.substring(i-1, i));
            // Check if successful two digit decode is possible.
            int twoDigit = Integer.valueOf(s.substring(i - 2, i));
            if(oneDigit>=1)
			{
				dp[i]+=dp[i - 1];
			}
			if (twoDigit >= 10 && twoDigit <= 26) 
			{
                dp[i] += dp[i - 2];
            }
        }

        return dp[n];
    }

	public static void main(String[] args) 
	{
		Scanner sc=new Scanner(System.in);
		String s=sc.next();
		System.out.println(numDecodings(s));
	}
}

