/*
Program1- Evalaute Expression Strings

Problem Statement

Given an expression in string format print the value of the expression 
after evaluating 

Rules for Evaluation :
The expression is Evaluated from Left to Right and operators allowed 
are only +,-,/,*
Ignore Operator Precedence and evaluate the expression from left to right
Assume the expression only consists of numbers(both positive and negative) and 
operators(+,-,*,/)

Test Case-1
input = 12+3*16
output = 240

Test Case-2
input = 5+17-9+0*10+12
output = 142

Test Case-3
input = -1+-15*24
output = -384

back end test cases
case = 1
input = 12*24+5
output = 293

case = 2
input = 7+17+27
output = 51

case = 3
input = 3*24-14
output = 58

case = 4
input = -12+-1*24
output = -312

case = 5
input = -11*-12+10-20/3
output = 40
*/
import java.util.*;
public class ExpressionEvaluator 
{
    public static int evaluate(String expr) 
	{
        if (expr == null || expr.isEmpty()) return 0;

        // Clean expression
        expr = expr.replaceAll(" ", "");

        // Handle negative numbers and split numbers/operators
        List<Integer> numbers = new ArrayList<>();
        List<Character> operators = new ArrayList<>();

        int i = 0;
        while (i < expr.length()) 
		{
            int num = 0;
            boolean negative = false;

            // Check for unary minus
            if (expr.charAt(i) == '-') 
			{
                negative = true;
                i++;
            }
			else if (expr.charAt(i) == '+') 
			{
                i++; // skip unary plus
            }

            // Read the full number
            if (i < expr.length() && Character.isDigit(expr.charAt(i))) 
			{
                while (i < expr.length() && Character.isDigit(expr.charAt(i))) 
				{
                    num = num * 10 + (expr.charAt(i) - '0');
                    i++;
                }
				if (negative) num = -num;
                numbers.add(num);
            }

            // Read operator
            if (i < expr.length() && "+-*/".indexOf(expr.charAt(i)) != -1) 
			{
                operators.add(expr.charAt(i));
                i++;
            }
        }

        // Evaluate left to right
        int result = numbers.get(0);
        for (int j = 0; j < operators.size(); j++) 
		{
            int next = numbers.get(j + 1);
            char op = operators.get(j);

            switch (op) 
			{
                case '+': result += next; 
							break;
                case '-': result -= next; 
							break;
                case '*': result *= next; 
							break;
                case '/': result /= next;
							break;
            }
        }

        return result;
    }
	public static void main(String[] args) 
	{
		Scanner s=new Scanner(System.in);
		String expr=s.next();
		System.out.println(evaluate(expr));
	}
}

