import java.util.*;
public class Hamiltonian
{
	static boolean found = false;
	static int n;
	static int x[];
	static int G[][];
	public static void main(String args[]) 
	{
		Scanner s=new Scanner(System.in);
		n = s.nextInt();
		G =new int[n+1][n+1];
		x =new int[n+1];
		for(int i=1;i<=n;i++)
		{
			for(int j=1;j<=n;j++)
			{
				G[i][j]=s.nextInt();
			}
		}
		x[1] = 1;
		Hamiltonian(2);
		if(found == false)
			System.out.println("No Solution");
	}

	static void Hamiltonian(int k)
	{
		while(true)
		{
			NextValue(k);
			if(x[k] == 0)
			return;
			if(k == n)
			{
				for(int i=1; i<=k;i++)
					System.out.print(x[i]+" ");
				System.out.println();
				found = true;
			}
			else
			Hamiltonian(k+1);
		}
	}
	static void NextValue(int k)
	{
		while(true)
		{
			x[k]=(x[k]+1)%(n+1);
			if(x[k] == 0)
			return;
			if(G[x[k-1]][x[k]] !=0)
			{
				int j;
				for(j=1; j<k; j++)
				{
					if(x[k] == x[j])
					break;
				}
				if(j==k)
				{
					if((k<n)||((k==n)&&G[x[n]][x[1]]!=0))
					return;
				}
			}
		}
	}
}

