       }

       int n3=sc.nextInt();
       int a3[]=new int[n3];
       for(int i=0;i<n3;i++)
       {
        a3[i]=sc.nextInt();
       }
        System.out.println(arraysIntersection(a1,a2,a3));
   }
}

