import java.util.*;
class KthMissingPositiveNumber
{
    public static int findKthPositive(int[] arr, int k)
    {
        int left = 0, right = arr.length;

        while(left < right)
		{
            int mid = (left + right) / 2;
            int missingCnt = arr[mid] - (mid + 1);

            if(missingCnt < k)
			{
                left = mid + 1;
            }
			else
			{
                right = mid;
            }
        }
        return k + left;
    }

	public static void main(String args[])
    {
