/*
In a school, 5th standard is having 2 sections called Rose and Lotus.
Section Rose contains 'm' students and Lotus contains 'n' students.
Each section's students scored marks in the Mathematics exam.
Teacher maintained a record of marks in ascending order of each section.
Now your task is to find out the median of the marks of 2 sections together.

Note: The overall run time complexity should be O(log (m+n)) .

Example 1:
Sample Input=
4  //m                                                                                                     
5  //n                                                                                                    
62 74 81 95         //Rose section marks                                                                                                    
40 59 67 73 84      //Lotus section marks                                                                                                    

Sample Output=
73.0  //median

Explanation: merged marks = [40 59 62 67 73 74 81 84 95] 
and median is 73.0

Example 2:
Sample Input=
4
4
61 71 82 95
42 51 64 83

Sample Output=
67.5

Explanation: merged marks = [42 51 61 64 71 82 83 95] 
and median is (64+71)/2 is 67.5

*/

import java.util.*;

class MedianSortedArrays 
{
	public double findMedianSortedArrays(int[] input1, int[] input2) 
	{
		//if input1 length is greater than switch them so that input1 is smaller than input2.
        if (input1.length > input2.length) 
		{
            return findMedianSortedArrays(input2, input1);
        }
        int x = input1.length;
        int y = input2.length;

        int low = 0;
        int high = x;
		double median=0.0;
        while (low <= high) 
		{
            int partitionX = (low + high)/2;
            int partitionY = (x + y + 1)/2 - partitionX;

            //if partitionX is 0 it means nothing is there on left side. 
			//Use Integer.MIN_VALUE for maxLeftX
            //if partitionX is length of input then there is nothing on right side. 
			//Use Integer.MAX_VALUE for minRightX
            int maxLeftX = (partitionX == 0) ? Integer.MIN_VALUE : input1[partitionX - 1];
            int minRightX = (partitionX == x) ? Integer.MAX_VALUE : input1[partitionX];

            int maxLeftY = (partitionY == 0) ? Integer.MIN_VALUE : input2[partitionY - 1];
            int minRightY = (partitionY == y) ? Integer.MAX_VALUE : input2[partitionY];

            if (maxLeftX <= minRightY && maxLeftY <= minRightX) 
			{
                // We have partitioned array at correct place
                // Now get max of left elements and min of right elements to get the 
				// median in case of even length combined
				// array size or get max of left for odd length combined array size.
                if ((x + y) % 2 == 0) 
				{
                    median= ((double)Math.max(maxLeftX, maxLeftY) + Math.min(minRightX, minRightY))/2;
                } 
				else
				{
                    median= (double)Math.max(maxLeftX, maxLeftY);
                }
				break;
            } 
			else if (maxLeftX > minRightY) 
			{ 
				//we are too far on right side for partitionX. Go on left side.
                high = partitionX - 1;
            } 
			else
			{ 
				//we are too far on left side for partitionX. Go on right side.
                low = partitionX + 1;
            }
        }
		return median;
	}

	public static void main(String[] args) 
	{ 
		Scanner sc=new Scanner(System.in);
		int m=sc.nextInt();
		int n=sc.nextInt();
		int[] A= new int[m];
		int[] B=new int[n];
		for(int i=0;i<m;i++)
			A[i]= sc.nextInt();
		for(int i=0;i<n;i++)
			B[i]= sc.nextInt();
		System.out.println( new MedianSortedArrays().findMedianSortedArrays(A,B) ); 
	} 
}

