import java.util.*;
public class MeetingRooms2 
{
    public static int minMeetingRooms(int[][] intervals) 
	{
        // Sort intervals by start time
        //Arrays.sort(intervals, (a, b) -> a[0] - b[0]);
		Arrays.sort(intervals, new Comparator<int[]>() 
		{
			public int compare(int[] a, int[] b) 
			{
				return a[0] - b[0];
			}
		});
        // Priority queue to store end times
        PriorityQueue<Integer> pq = new PriorityQueue<>();

        for (int i = 0; i < intervals.length; i++) 
		{
            // If a room is free (earliest end time <= current start time), reuse it
            if (!pq.isEmpty() && pq.peek() <= intervals[i][0]) 
			{
                pq.poll();
            }
            // Allocate room for the current meeting
            pq.offer(intervals[i][1]);
        }

        // Size of the priority queue is the number of rooms needed
        return pq.size();
    }

    public static void main(String[] args) 
	{
        Scanner s = new Scanner(System.in);

        // Input number of meetings
        int n = s.nextInt();

        // Input each meeting's start and end time
        int[][] intervals = new int[n][2];
        for (int i = 0; i < n; i++) 
		{
            intervals[i][0] = s.nextInt(); // start time
            intervals[i][1] = s.nextInt(); // end time
        }

        // Output the result
        int result = minMeetingRooms(intervals);
        System.out.println(result);
    }
}

