/*
931. Minimum Falling Path Sum
Given an n x n array of integers matrix, return the minimum sum of any 
falling path through matrix.

A falling path starts at any element in the first row and chooses the 
element in the next row that is either directly below or diagonally left/right.
Specifically, the next element from position (row, col) will be 
(row + 1, col - 1), (row + 1, col), or (row + 1, col + 1).

Example 1:
Input: 
3  //rows 
3  //columns
2 1 3
6 5 4
7 8 9
Output: 13

Example 2:
Input: 
2 2
-19 57
-40 -5
Output: -59
*/
import java.util.*;
class  MinFallingSum
{
	public static int minFallingPathSum(int[][] a) 
	{
        int m = a.length;
        int n = a[0].length;
        int[][] dp = new int[101][101];

        // Initialize the first row of dp with the first row of matrix
        for (int i = 0; i < n; i++) 
		{
            dp[0][i] = a[0][i];
        }

        // Fill the dp table
        for (int i = 1; i < m; i++)
		{
            for (int j = 0; j < n; j++) 
			{
                int min = Integer.MAX_VALUE;
                min = Math.min(min, dp[i - 1][j]);
                if (j - 1 >= 0) 
				{
                    min = Math.min(min, dp[i - 1][j - 1]);
                }
                if (j + 1 < m) 
				{
                    min = Math.min(min, dp[i - 1][j + 1]);
                }
                dp[i][j] = min + a[i][j];
            }
        }

        // Find the minimum value in the last row of dp
        int ans = dp[m - 1][0];
        for (int i = 1; i < n; i++)
		{
            ans = Math.min(ans, dp[m - 1][i]);
        }

        return ans;
    }
	public static void main(String[] args) 
	{
		Scanner s=new Scanner(System.in);
		//int m=s.nextInt();
		int n=s.nextInt();
		int a[][]=new int[n][n];
		for(int i=0;i<n;i++)
		{
			for(int j=0;j<n;j++)
			{
				a[i][j]=s.nextInt();
			}
		}
		System.out.println(minFallingPathSum(a));
	}
}

