import java.util.*;
class  MinFlips
{
	public static int minFlips(String s) 
	{
        int oneEven=0 , oneOdd=0 , zeroEven= 0, zeroOdd = 0;
        for(int i=0;i<s.length();i++)
		{
            if(s.charAt(i) == '1')
			{
                if(i%2==0)
                    oneEven++;
                else
                    oneOdd++;
            }
            else
			{
                if(i%2==0)
                    zeroEven++;
                else
                    zeroOdd++;
            }
        }
        int minFlips = Math.min(zeroEven+oneOdd,zeroOdd+oneEven);
         if (s.length() % 2 != 0)
		 {
            for (int i = 0; i < s.length(); i++) 
			{
                if (s.charAt(i) == '1') 
				{
                    oneEven--; 
                    oneOdd++;
                } 
				else 
				{
                    zeroEven--; 
                    zeroOdd++;
                }

                int tempOneEven = oneEven;
                oneEven = oneOdd;
                oneOdd = tempOneEven;

                int tempZeroEven = zeroEven;
                zeroEven = zeroOdd;
                zeroOdd = tempZeroEven;

                minFlips = Math.min(minFlips, Math.min(zeroEven + oneOdd,
					zeroOdd + oneEven));
            }
        }
        return minFlips;
    }
	public static void main(String[] args) 
	{
		Scanner sc=new Scanner(System.in);
		String s=sc.next();
		System.out.println(minFlips(s));
	}
}
