import java.util.*;
class MS 
{
	public static int minEatingSpeed(int piles[],int h)
	{
		int max=Integer.MIN_VALUE;
		//find the maximum value in the piles array based on which binary search is to be done
		for(int val:piles)
		{
			max=Math.max(val,max);
		}
		//if number of hours is equal to number of piles return the max value as answer
		if(h==piles.length)
		{
			return max;
		}

		int l=0,u=max;
		int speed=Integer.MAX_VALUE;
		while(l<=u)
		{
			int k=(l+u)/2;
			//if it is possible to eat k bananas in every hour update upper bound to 
			//k(mid)-1  and update speed to k else update lower bound to k+1. 
			//Repeat until l<=u
			if(isPossible(piles,k,h))
			{
				speed=k;
				u=k-1;
			}
			else
			{
				l=k+1;
			}
		}
		return speed;
	}
	static boolean isPossible(int piles[],int k,int h)
	{
		int time=0;
		for(int i=0;i<piles.length;i++)
		{
			time+=Math.ceil((piles[i]*1.0)/k);
		}
		return time<=h;
	}
	public static void main(String[] args) 
	{
		Scanner s=new Scanner(System.in);
		System.out.println("Enter number of piles");
		int n=s.nextInt();
		int a[]=new int[n];
		System.out.println("Enter number of bananas in each pile");
		for(int i=0;i<n;i++)
			a[i]=s.nextInt();
		System.out.println("Enter number of hours");
		int h=s.nextInt();
		System.out.println(minEatingSpeed(a,h));

	}
}

/*
Akbar used to play chess with Birbal almost every evening.
Once Akbar has challanged Birbal to place the queens in each row of the board,
such that no queen should attack another queen on the board.

You are given an integer N, indicates the size of the board as N*N.
Your task is to help Birbal to find and win in this challange, 
if there is a solution, print the answer as shown in the samples
Otherwise, print "No Solution"

Input Format:
-------------
An integer N, size of the chess board.

Output Format:
--------------
Print any possible solution.


Sample Input-1:
---------------
4

Sample Output-1:
------------------
2 4 1 3
3 1 4 2
*/

import java.util.*;
class NQueens
{
	int x[]=new int[20];
	public boolean place(int k,int i)
	{
		int j;
		for(j=1;j<=k-1;j++)
		{ 
			//checking for column and diagonal conflicts
			if((x[j]==i)|(Math.abs(x[j]-i)==Math.abs(j-k)))
			return false;
		}
		return true;
	}

	public void queen(int k,int n)
	{
		int i;
		for(i=1;i<=n;i++)
		{
			if(place(k,i))
			{
				x[k]=i;
				if(k==n)
				{
					for(int l=1;l<=n;l++)
					{
						System.out.print(x[l]+" ");
					}
					System.out.println();
				}
				else //try next queen with next position
				queen(k+1,n);
			}
		}
	}
	public static void main (String args[] ) 
	{
		Scanner s=new Scanner(System.in);
		int n=s.nextInt();
		NQueens nq=new NQueens();
		nq.queen(1,n);
	}
}

