output=
false

case=2
input= 1 2 3 -1 4 -1 5 
5
4
output=
true


case=3
input= 1 2 3 -1 4
2
3
output=
false

Approach:
---------
Use BFS (Level Order Traversal):

Traverse the tree level by level.
Keep track of nodes and their parents at each level.
Check for Cousins:

If x and y are found on the same level but have different parents, they are cousins.
If both nodes are found but have the same parent, they are not cousins.
If only one node is found at a level, they are not cousins.
*/
import java.util.*;
class Node 
{
    int val;
    Node left, right;

    Node(int value) 
    {
        this.val = value;
    }
}

class Test
{
    public static void main(String[] args)
     {
        Scanner sc = new Scanner(System.in);

       String[] arr = sc.nextLine().split(" ");
       int x=sc.nextInt();
        int y=sc.nextInt();
       List<Integer> v = new ArrayList<>();
        for (String s : arr) 
        {
            v.add(Integer.parseInt(s));
        }
         Node root = buildTree(v);



        System.out.println(new Solution().isCousins(root,x,y));
    }

    private static Node buildTree(List<Integer> v) 
    {
        if (v == null || v.isEmpty() || v.get(0) == -1) 
        {
            return null;
        }

        Node root = new Node(v.get(0));//1
        Queue<Node> q = new LinkedList<>();
        q.add(root);

        int i = 1;
        while (i < v.size())
         {
            Node current = q.poll();

            if (i < v.size() && v.get(i) != -1) 
            {
                current.left = new Node(v.get(i));
                q.add(current.left);
            }
            i++;


            if (i < v.size() && v.get(i) != -1)
             {
                current.right = new Node(v.get(i));
                q.add(current.right);
            }
            i++;
        }

        return root;
    }
}

 class Solution
  {
    Node xParent = null;

    Node yParent = null;

    int xDepth = -1, yDepth = -1;

    public boolean isCousins(Node root, int x, int y) 
    {
        helper(root,x,y,0,null);

        return xDepth == yDepth && xParent != yParent? true:false;

    }

    public void helper(Node root, int x, int y, int depth, Node parent)
    {
        if(root == null)
        {
             return;
        }
        if(root.val==x)
        {
            xParent=parent;
            xDepth=depth;
        }

        if(root.val==y)
        {
            yParent=parent;
            yDepth=depth;
        }

        helper(root.left,x,y,depth+1,root);
       helper(root.right,x,y,depth+1,root);

    }
}

