            v.add(Integer.parseInt(s));
        }

       List<Integer> v1 = new ArrayList<>();
        for (String s : arr1) 
        {
            v1.add(Integer.parseInt(s));
        }

         Node root1 = buildTree(v);
         Node root2 = buildTree(v1);
        System.out.println(new Solution().leafSimilar(root1,root2));
    }

    private static Node buildTree(List<Integer> v) 
    {
        if (v == null || v.isEmpty() || v.get(0) == -1) 
        {
            return null;
        }

        Node root = new Node(v.get(0));//1
        Queue<Node> q = new LinkedList<>();
        q.add(root);

        int i = 1;
        while (i < v.size())
         {
            Node current = q.poll();

            if (i < v.size() && v.get(i) != -1) 
            {
                current.left = new Node(v.get(i));
                q.add(current.left);
            }
            i++;


            if (i < v.size() && v.get(i) != -1)
             {
                current.right = new Node(v.get(i));
                q.add(current.right);
            }
            i++;
        }

        return root;
    }
}

class Solution 
{
    public boolean leafSimilar(Node root1, Node root2) 
    {
        List<Integer> leafValues1 = new ArrayList<>();
        List<Integer> leafValues2 = new ArrayList<>();

        collectLeafValues(root1, leafValues1);
        collectLeafValues(root2, leafValues2);

        return leafValues1.equals(leafValues2);
    }

    private void collectLeafValues(Node root, List<Integer> leafValues) 
    {
        if (root == null) {
            return;
        }
        if (root.left == null && root.right == null) 
        {
            leafValues.add(root.val);
        }
        collectLeafValues(root.left, leafValues);
        collectLeafValues(root.right, leafValues);
    }
}


