import java.util.*;
class RelativelySmallestString 
{
	static int p[];
	public static String smallestString(String A, String B, String S)
	{
		p=new int[26];
        for(int i = 0; i < 26; i++) 
		{
            p[i] = -1;
        }
        for(int i = 0; i < A.length(); i++) 
		{
            int a = A.charAt(i) - 'a';
            int b = B.charAt(i) - 'a';
            int end1 = find(a);
            int end2 = find(b);
            if(end1 < end2) 
			{
                p[end2] = end1;
            } 
			else if(end1>end2)
			{
                p[end1] = end2;
            }
        }
