        for(int i = 0; i < S.length(); i++) 
		{
            int c = S.charAt(i)-'a';
            sb.append((char)('a' + find(c)));
		}
        return sb.toString();
    }

    static int find(int i) 
	{
        while(p[i]>=0)
	    i=p[i];
