Explanation -
-1 + -1 is -2 
and -2 * 2 is -4

back end test cases
case = 1
input = 1*2+5
output = 7

case = 2
input = 7+7+7
output = 21

case = 3
input = 3*4-4
output = 8

case = 4
input = -1+-1*2
output = -4

case = 5
input = -1*-1
output = 1
*/
import java.util.*;
public class SimpleExpressionEvaluator 
{
    public static int evaluate(String expr) 
	{
        if (expr == null || expr.isEmpty()) return 0;

        // Clean expression
        expr = expr.replaceAll(" ", "");

        // Handle negative numbers and split numbers/operators
       List<Integer> numbers = new ArrayList<>();
       List<Character> operators = new ArrayList<>();

        int i = 0;
        while (i < expr.length()) 
		{
            int num = 0;
            boolean negative = false;

            // Check for unary minus
            if (expr.charAt(i) == '-') 
			{
                negative = true;
                i++;
            }
			else if (expr.charAt(i) == '+') 
			{
                i++; // skip unary plus
            }

            // Read the full number
            if (i < expr.length() && Character.isDigit(expr.charAt(i))) 
			{
//                while (i < expr.length() && Character.isDigit(expr.charAt(i))) 
//				{
//                    num = num * 10 + (expr.charAt(i) - '0');
//                    i++;
//              }
				num = expr.charAt(i) - '0';
				i++;
                if (negative) num = -num;
                numbers.add(num);
            }

            // Read operator
            if (i < expr.length() && "+-*/".indexOf(expr.charAt(i)) != -1) 
			{
                operators.add(expr.charAt(i));
                i++;
            }
        }

        // Evaluate left to right
        int result = numbers.get(0);
        for (int j = 0; j < operators.size(); j++) 
		{
            int next = numbers.get(j + 1);
            char op = operators.get(j);

            switch (op) 
			{
                case '+': result += next; 
							break;
                case '-': result -= next; 
							break;
                case '*': result *= next; 
							break;
                case '/': result /= next;
							break;
            }
        }

        return result;
    }
	public static void main(String[] args) 
	{
		Scanner s=new Scanner(System.in);
		String expr=s.next();
		System.out.println(evaluate(expr));
	}
}

