output=
3

case=8
input=
T?T?T?9:8:7:6
output=
9


*/
import java.util.*;
class TEP
{
	public static String parseTernary(String expression) 
	{
       Stack<Character> stk = new Stack<>();
        boolean cond = false;
        for (int i = expression.length() - 1; i >= 0; --i) 
		{
            char c = expression.charAt(i);
            if (c == ':') 
			{
                continue;
            }
            if (c == '?') 
			{
                cond = true;
            } 
			else 
			{
                if (cond) 
				{
                    if (c == 'T') 
					{
                        char x = stk.pop();
                        stk.pop();
                        stk.push(x);
                    } 
					else 
					{
                        stk.pop();
                    }
                    cond = false;
                } 
				else 
				{
                    stk.push(c);
                }
            }
        }
        return String.valueOf(stk.peek());
    }
	public static void main(String[] args) 
	{
		Scanner sc=new Scanner(System.in);
		String s=sc.next();
		System.out.println(parseTernary(s));
	}
}

/*
98. Validate Binary Search Tree
Given the root of a binary tree, determine if it is a valid binary search 
tree (BST).

A valid BST is defined as follows:

The left subtree of a node contains only nodes with keys less than the node's
key.
The right subtree of a node contains only nodes with keys greater than the
node's key.
Both the left and right subtrees must also be binary search trees.

Example 1:

Input: 
2 1 3
Output: true

Example 2:

Input: 
5 1 4 -1 -1 3 6
Output: false
Explanation: The root node's value is 5 but its right child's value is 4.
*/

import java.util.*;

class BinaryTreeNode
{
	public int data; 
	public BinaryTreeNode left, right; 
	public BinaryTreeNode(int data)
	{
		this.data = data; 
		left = null; 
		right = null; 
	}
}

class ValidateBST
{
	static BinaryTreeNode root;
	void insert(BinaryTreeNode temp, int key)
    {

        if (temp == null) 
		{
            root = new BinaryTreeNode(key);
            return;
        }
        Queue<BinaryTreeNode> q = new LinkedList<BinaryTreeNode>();
        q.add(temp);

        // Do level order traversal until we find
        // an empty place.
        while (!q.isEmpty()) 
		{
            temp = q.peek();
            q.remove();

            if (temp.left == null) 
			{
                temp.left = new BinaryTreeNode(key);
                break;
            }
            else
                q.add(temp.left);

            if (temp.right == null) 
			{
                temp.right = new BinaryTreeNode(key);
                break;
            }
            else
                q.add(temp.right);
        }
    }

	public static boolean check(BinaryTreeNode root, long minVal, long maxVal) 
	{
        if (root == null||root.data==-1) 
			return true;
        if (root.data <= minVal || root.data >= maxVal) 
			return false;

        return check(root.left, minVal, root.data) && check(root.right, root.data, maxVal);
    }

    public static boolean isValidBST(BinaryTreeNode root) 
	{
        return check(root, Long.MIN_VALUE, Long.MAX_VALUE);
    }
	public static void main(String args[])
	{
		Scanner sc=new Scanner(System.in);
		String str[]=sc.nextLine().split(" ");
		ValidateBST st=new ValidateBST();
		root=new BinaryTreeNode(Integer.parseInt(str[0]));
		for(int i=1; i<str.length; i++)
			st.insert(root,Integer.parseInt(str[i]));
		System.out.println(isValidBST(root));
	}
}

