    for (int i : graph[val]) { // ?? Explore neighbors
        if (!visit[i]) { // ? Skip visited nodes
            cur.add(i); // ? Add neighbor to path
            dfs(graph, i, cur, visit, ans); // ?? Recurse
            cur.removeLast(); // ?? Backtrack
        }
    }

    visit[val] = false; // ?? Reset visit status for other paths
}
