/*Perform Arithmetic operations using recursion

Sample Input and Output:
input=8 2
output=Sum is: 10
Difference is: 6
Product is: 16
Quotient is: 4

input=18 3
output=Sum is: 21
Difference is: 15
Product is: 54
Quotient is: 6

*/
import java.util.*;
class  Arithmetic
{
	// Add 2 values using recursion

	public static int add(int a, int b)
	{
			// Base case: if b is 0, return a
			if (b == 0) 
			{
				return a;
			}
			// Recursive call: increment a and decrement b
			return add(a + 1, b - 1);
	}

	// Multiply 2 positive values using recursion

	public static int multiply(int a, int b) 
	{
			// Base case: if b is 0, return 0
			if (b == 0) 
			{
				return 0;
			}
			// Recursive call: add 'a' to the result of multiply(a, b-1)
			return a + multiply(a, b - 1);
	}

	// Recursive function to subtract two numbers
	public static int subtract(int a, int b) 
	{
			// Base case: if b is 0, return a
			if (b == 0) {
				return a;
			}
			// Decrease b and decrease a to simulate subtraction
			return subtract(a - 1, b - 1);
	}

	// Recursive function to perform integer division
	public static int divide(int dividend, int divisor) 
	{
			// Base case: If dividend is smaller than divisor, return 0
			if (dividend < divisor) {
				return 0;
			}
			// Subtract divisor from dividend and count the quotient
			return 1 + divide(dividend - divisor, divisor);
	}

	public static void main(String[] args) 
	{
		Scanner s=new Scanner(System.in);
		int a=s.nextInt();
		int b=s.nextInt();
		System.out.println("Sum is: "+add(a,b));
		System.out.println("Difference is: "+subtract(a,b));
		System.out.println("Product is: "+multiply(a,b));
		System.out.println("Quotient is: "+divide(a,b));
	}
}
