*/
import java.util.*;
class  ArrayProblems
{
	public static int sumOfArray(int[] a, int n) 
	{
        // Base case: if n reaches 0, return a[0]
        if (n ==0) {
            return a[0];
        }
        // Recursive case: sum of current element + sum of remaining elements
        return a[n] + sumOfArray(a, n - 1);
    }

	public static int findMax(int[] arr, int index) 
	{
        // Base case: if we reach the last element, return it
        if (index == arr.length - 1) 
		{
            return arr[index];
        }

        // Recursive case: get the maximum of the rest of the array
        int maxInRest = findMax(arr, index + 1);

        // Return the maximum between the current element and the max of the rest
        return Math.max(arr[index], maxInRest);
    }

	public static int linearSearch(int[] arr, int index, int target) 
	{
        // Base case: If index reaches the end of the array, return -1 (not found)
        if (index == arr.length) 
		{
            return -1;
        }

        // If the current element matches the target, return the index
        if (arr[index] == target) 
		{
            return index+1;
        }

        // Recursively search in the rest of the array
        return linearSearch(arr, index + 1, target);
     }

	 public static boolean isSorted(int[] arr, int index) 
	 {
        // Base case: If we have reached the last element or empty array
        if (index == arr.length - 1 || arr.length == 0) {
            return true;
        }
        // If the current element is greater than the next one, return false
        if (arr[index] > arr[index + 1]) {
            return false;
        }
        // Recursively check for the next element
        return isSorted(arr, index + 1);
    }

	public static int binarySearch(int[] arr, int left, int right, int target) 
	{
        // Base case: If the range is invalid, the element is not found
        if (left > right) 
		{
            return -1;
        }
        int mid = (left + right) / 2;
        if (arr[mid] > target) 
		{
            return binarySearch(arr, left, mid - 1, target);
        }
        else if(arr[mid] < target)
		{
           return binarySearch(arr, mid + 1, right, target);
		}
        else
		{
            return mid+1;
        }
    }


	public static void main(String[] args) 
	{
		Scanner s=new Scanner(System.in);
		int n=s.nextInt();
		int a[]=new int[n];
		for(int i=0;i<n;i++)
			a[i]=s.nextInt();
		System.out.println(sumOfArray(a,n-1));
		System.out.println(findMax(a, 0)); 

		int arr1[]=new int[n];
		for(int i=0;i<n;i++)
			arr1[i]=s.nextInt();
		int target=s.nextInt();
		System.out.println(linearSearch(arr1,0,target));

		int arr2[]=new int[n];
		for(int i=0;i<n;i++)
			arr2[i]=s.nextInt();
		System.out.println(isSorted(arr2,0));

		int arr3[]=new int[n];
		for(int i=0;i<n;i++)
			arr3[i]=s.nextInt();
		target=s.nextInt();
		System.out.println(binarySearch(arr3,0,n-1,target)); 
	}
}

