import java.util.*;
class BFS 
{
	static int q[]=new int[20];
	static int f=-1,r=-1;

	static void qinsert(int x)
	{
		r++;
		q[r]=x;
		if(f==-1)  
			f=0;
	}

	static int qdelete()
	{
		if(f==-1)
			return 0;
		int x=q[f];
		if(f==r)  
			f=r=-1;  
		else
			f++;
		return x;
	}

	static void bfs(int a[][],int v)
	{
		int n=a.length;
		int visited[]=new int[a.length];

		qinsert(v);   
		visited[v]=1;

		int u=v;  

		while(true)
		{
			for(int i=1;i<n;i++)
			{  
				if(a[u][i]==1&&visited[i]==0)
				{
					qinsert(i);
					visited[i]=1;
				}
			}
			int x=qdelete();  
			if(x!=0) 
				System.out.print(" "+x);  
			if(f==-1)  
				break; 
			u=q[f];  
