/*
In a binary tree, a lonely node is a node that is the only child of its parent node. The root of the tree is not lonely because it does not have a parent node.

Given the root of a binary tree, return an List(Array) containing the values of all lonely nodes in the tree using Breadth First Search Mechanism. Return the list in any order.

Sample Input and Output:
Input: root = [1,2,3,null,4]
Output: [4]
*/
import java.util.*;

class BinaryTreeNode
{
	public int data; 
	public BinaryTreeNode left, right; 
	public BinaryTreeNode(int data)
	{
		this.data = data; 
		left = null; 
		right = null; 
	}
}

class Solution
{
    public List<Integer> getLonelyNodes(BinaryTreeNode root) 
    {
        List<Integer> lonelyNodes = new ArrayList<Integer>();
        if (root == null)
            return lonelyNodes;
        Queue<BinaryTreeNode> q = new LinkedList<BinaryTreeNode>();
        q.offer(root);
        while (!q.isEmpty()) 
		{
            BinaryTreeNode node = q.poll();
            if (node.left != null) 
			{
				if(node.right==null)
                lonelyNodes.add(node.left.data);
                q.offer(node.left);
            } 
			if (node.right != null) 
			{
				if(node.left==null)
					lonelyNodes.add(node.right.data);
                q.offer(node.right);
            }
        }
        return lonelyNodes;
    }
}
public class BFSLonelyNodes
{
	public static void main(String args[])
	{
		Scanner sc=new Scanner(System.in);
		Solution sol= new Solution();
		BinaryTreeNode root = new BinaryTreeNode(1); 
		root.left = new BinaryTreeNode(2); 
		root.right = new BinaryTreeNode(3); 
		root.left.right = new BinaryTreeNode(4); 
		root.right.left = new BinaryTreeNode(5); 
		root.right.left.left = new BinaryTreeNode(6); 
		System.out.println(sol.getLonelyNodes(root));
	}
}

