/*
In a magical forest, trees are planted following a special rule forming a binary tree  each
tree has at most two child trees (left and right).
The forest guardians want to protect the outermost trees  that is:
First, they walk along the leftmost edge of the forest (from top to bottom),
Then, they observe all the leaf trees (trees with no children),
Finally, they walk along the rightmost edge of the forest (from bottom to top).
They want to list the boundary trees in this exact order to create a magical shield.
You are given the root of the forest (binary tree).
Return the list of values of the trees that are on the boundary of the forest, according to
the guardians' walk.
*/
import java.util.*;

public class BinaryTreeBoundaryBFS {

    public static void main(String[] args) {
        // create a binary tree
        TreeNode root = new TreeNode(20);
		root.left = new TreeNode(8);
		root.left.left=new TreeNode(4);
		root.left.right = new TreeNode(12);
        root.left.right.left = new TreeNode(10);
        root.left.right.right = new TreeNode(14);
        root.right = new TreeNode(22);
        root.right.right = new TreeNode(25);

        // print the boundary of the binary tree
        List<Integer> boundary = getBoundary(root);
        System.out.println(boundary);
    }

    public static List<Integer> getBoundary(TreeNode root) 
	{
        List<Integer> boundary = new ArrayList<>();

        if (root == null) 
		{
            return boundary;
        }

        // add the root node to the boundary
        boundary.add(root.val);

        // add the left boundary
        Queue<TreeNode> queue = new LinkedList<>();
        if (root.left != null) 
		{
            queue.offer(root.left);
        }
        while (!queue.isEmpty()) 
		{
            TreeNode node = queue.poll();
            if (node.left != null) 
			{
                boundary.add(node.val);
                queue.offer(node.left);
            } 
			else if (node.right != null) 
			{
                boundary.add(node.val);
                queue.offer(node.right);
            }
        }

        // add the leaf nodes
        addLeaves(root, boundary);

        // add the right boundary
        Stack<Integer> stack = new Stack<>();
        if (root.right != null) 
		{
            queue.offer(root.right);
        }
        while (!queue.isEmpty()) 
		{
            TreeNode node = queue.poll();
            if (node.right != null) 
			{
                stack.push(node.val);
                queue.offer(node.right);
            } 
			else if (node.left != null) 
			{
                stack.push(node.val);
                queue.offer(node.left);
            }
        }
        while (!stack.isEmpty()) 
		{
            boundary.add(stack.pop());
        }

        return boundary;
    }

    private static void addLeaves(TreeNode node, List<Integer> boundary) {
        if (node == null) {
            return;
        }
        if (node.left == null && node.right == null) {
            boundary.add(node.val);
        }
        addLeaves(node.left, boundary);
        addLeaves(node.right, boundary);
    }
}

class TreeNode {
    int val;
    TreeNode left;
    TreeNode right;

    TreeNode(int val) {
        this.val = val;
    }
}

