import java.util.*;

class BinaryTreeNode{
	public int data; 
	public BinaryTreeNode left, right; 
	public BinaryTreeNode(int data)
	{
		this.data = data; 
		left = null; 
		right = null; 
	}
}

public class BoundaryOfBinaryTreeDFS
{
	static List<Integer> nodes = new ArrayList<>();
	public static List<Integer> boundaryOfBinaryTree(BinaryTreeNode root) 
	{
        if(root == null)
			return nodes;

        nodes.add(root.data);
        leftBoundary(root.left);
        leaves(root.left);
        leaves(root.right);
        rightBoundary(root.right);

        return nodes;
    }
    public static void leftBoundary(BinaryTreeNode root) 
	{
        if(root == null || (root.left == null && root.right == null))
        return;
        nodes.add(root.data);
        if(root.left == null)
			leftBoundary(root.right);
        else 
			leftBoundary(root.left);
    }
    public static void rightBoundary(BinaryTreeNode root) 
	{
        if(root == null || (root.left == null&& root.right == null))
			return;
        if(root.right == null)
			rightBoundary(root.left);
        else
			rightBoundary(root.right);
        nodes.add(root.data); // add after child visit(reverse)
    }
    public static void leaves(BinaryTreeNode root) 
	{
        if(root == null)
			return;
        if(root.left == null && root.right == null)
		{
            nodes.add(root.data);
            return;
        }
        leaves(root.left);
        leaves(root.right);
    }

	public static void main(String args[])
	{
		Scanner sc=new Scanner(System.in);
		BinaryTreeNode root = new BinaryTreeNode(7);
