import java.util.*;
class BraceExpansion 
{
	public static List<String> getAllExpansions(String s) 
	{
        List<String> res = new ArrayList<>();
        get(s, 0, "", res);
        return res;
    }

    private static void get(String s, int start, String cur, List<String> res) 
	{
        if (start == s.length()) 
		{
            res.add(cur);
            return;
        }
        int left = s.indexOf('{', start);
        int right = s.indexOf('}', start);
        if (left == -1) 
		{
            res.add(cur + s.substring(start));
            return;
        }
        String sub = s.substring(left + 1, right);
        String[] strs = sub.split(",");
        for (String str : strs) 
		{
            get(s, right + 1, cur + s.substring(start, left) + str, res);
        }
    }
	public static void main(String[] args) 
	{
		Scanner sc=new Scanner(System.in);
		System.out.println("Enter an expression");
		String s=sc.next();
		System.out.println(getAllExpansions(s));
	}
}

/*
This program creates a Graph object with an adjacency matrix representation and adds some edges to it. It then calls the bridge()
method on the graph object to find the bridges in the graph using DFS. The bridgeUtil() method is a recursive helper function that 
uses the disc[] and low[] arrays to find the bridges. The program prints the bridges it finds to the console.
*/

import java.util.*;

class Graph {
    private int V; // number of vertices
    private int[][] adj; // adjacency matrix
    private int time; // time used in DFS

    public Graph(int V) {
        this.V = V;
        adj = new int[V][V];
    }

    // add an edge to the graph
    public void addEdge(int v, int w) {
        adj[v][w] = 1;
        adj[w][v] = 1;
    }

    // utility function to find bridges in the graph
    private void bridgeUtil(int u, boolean[] visited, int[] disc, int[] low, int[] parent) {
        // mark current node as visited and initialize discovery time and low value
        visited[u] = true;
        disc[u] = low[u] = ++time;

        // loop through all vertices adjacent to this vertex
        for (int v = 0; v < V; v++) {
            if (adj[u][v] == 1) {
                // if v is not visited yet, then recur for it
                if (!visited[v]) {
                    parent[v] = u;
                    bridgeUtil(v, visited, disc, low, parent);

                    // check if the subtree rooted with v has a connection to one of the ancestors of u
                    low[u] = Math.min(low[u], low[v]);

                    // if the lowest vertex reachable from subtree under v is below u in DFS tree, then u-v is a bridge
                    if (low[v] > disc[u]) {
                        System.out.println(u + " " + v);
                    }
                }

                // update low value of u for parent function calls
                else if (v != parent[u]) {
                    low[u] = Math.min(low[u], disc[v]);
                }
            }
        }
    }

    // main function to find bridges in the graph
    public void bridge() {
        boolean[] visited = new boolean[V];
        int[] disc = new int[V];
        int[] low = new int[V];
        int[] parent = new int[V];

        // initialize parent and visited arrays
        for (int i = 0; i < V; i++) {
            parent[i] = -1;
            visited[i] = false;
        }

        // call the recursive helper function to find bridges
        for (int i = 0; i < V; i++) {
            if (!visited[i]) {
                bridgeUtil(i, visited, disc, low, parent);
            }
        }
    }
}

