/*
Given two sorted arrays and a number x, find the pair whose sum is closest to x and the pair has an element from each array. 
We are given two arrays ar1[0m-1] and ar2[0..n-1] and a number x, we need to find the pair ar1[i] + ar2[j] such that absolute value of (ar1[i] + ar2[j]  x) is minimum. 

Example-1:
Input: a[] = {1, 4, 5, 7}
b[] = {10, 20, 30, 40}
x = 32
Output: 1 and 30

Example-2:
Input: a[] = {1, 4, 5, 7}
b[] = {10, 20, 30, 40}
x = 50
Output: 7 and 40
*/

import java.util.*;

class ClosestPair
{
	public static void  printClosest(int a[], int b[], int m, int n, int x)
	{
		// Initialize the diff between pair sum and x.

		int diff = Integer.MAX_VALUE;

		// res_l and res_r are result indexes from ar1[] and ar2[] respectively
		int res_l = 0, res_r = 0;

		// Start from left side of ar1[] and right side of ar2[]
		int l = 0, r = n-1;

		while (l<m && r>=0)
		{
		// If this pair is closer to x than the previously found closest, 
		// then update res_l, res_r and diff

		if (Math.abs(a[l] + b[r] - x) < diff)
		{
			res_l = l;
			res_r = r;
			diff = Math.abs(a[l] + b[r] - x);
		}

		// If sum of this pair is more than x, move to smaller side

		if (a[l] + b[r] > x)
			r--;
		else // move to the greater side
			l++;
		}

		// Print the result
		System.out.print( a[res_l] +	" " + b[res_r] );
	}

	public static void main(String args[])
	{
