/*
77. Combinations


Given two integers n and k, return all possible combinations of k numbers chosen 
from the range [1, n].

You may return the answer in any order.


Example 1:

Input: 
4  //n
2  //k
Output: [[1,2],[1,3],[1,4],[2,3],[2,4],[3,4]]

Explanation: There are 4 choose 2 = 6 total combinations.
Note that combinations are unordered, i.e., [1,2] and [2,1] are considered to be the same combination.

Example 2:

Input: 
1
1
Output: [[1]]
Explanation: There is 1 choose 1 = 1 total combination.
*/
import java.util.*;
class Combinations
{
	private int n;
    private int k;

    public List<List<Integer>> combine(int n, int k) 
	{
        this.n = n;
        this.k = k;
        List<List<Integer>> ans = new ArrayList<>();
        backtrack(new ArrayList<>(), 1, ans);
        return ans;
    }

	public void backtrack(List<Integer> curr, int firstNum, List<List<Integer>> ans) 
	{
		if (curr.size() == k) 
		{
			ans.add(new ArrayList<>(curr));
			return;
		}

		for (int num = firstNum; num <= n; num++) 
		{
			curr.add(num);
			backtrack(curr, num + 1, ans);
			curr.remove(curr.size() - 1);
		}
		return;
	}
	public static void main(String[] args) 
	{
		Scanner sc=new Scanner(System.in);
		int n=sc.nextInt();
		int k=sc.nextInt();
		System.out.println(new Combinations().combine(n,k));
	}
}

