/*
There are N cities, and M routes[], each route is a path between two cities.
routes[i] = [city1, city2], there is a travel route between city1 and city2.
Each city is numbered from 1 to N.

There are one or more Regions formed among N cities. 
A Region is formed in such way that you can travel between any two cities 
in the region that are connected directly and indirectly.

Your task is to findout the number of regions formed between N cities. 
Assume 0 also as vertex

Input Format:
-------------
Line-1: number of cities N
Line-2: number of routes M
M routes

Sample Input-1:
---------------
5  //no of vertices
4  //no. of edges
0 1
0 2
1 2
3 4

Sample Output-1:
----------------
2


Sample Input-2:
---------------
5 
6
0 1
0 2
2 3
1 2
1 4
2 4

Sample Output-2:
----------------
1

*/

import java.util.*;

class ConnectedComponentsUF 
{
	int[] parent;
	int[] size;
    public int countComponents(int n, int[][] edges)
    {
        parent = new int[n];
        size = new int[n];
        for (int i = 0; i < n; i++) 
		{
            parent[i] = -1;
            size[i] = 1;
        }
        int components = n;
        for (int[] e : edges)
		{
            int p1 = find(e[0]);
            int p2 = find(e[1]);
            if (p1 != p2) 
			{
                if (size[p1] < size[p2]) 
				{ // Merge small size to large size
                    size[p2] += size[p1];
                    parent[p1] = p2;
                } 
				else 
				{
                    size[p1] += size[p2];
                    parent[p2] = p1;
                }
                components--;
            }
        }
        return components;
    }
    private int find(int i) 
	{
		while(parent[i]>=0)
			i = parent[i]; 
		return i;
     }

	public static void main(String args[])
	{
		Scanner sc= new Scanner(System.in);
		int n=sc.nextInt();
		int e=sc.nextInt();
		int edges[][]=new int[e][2]; 
		for(int i=0;i<e;i++)
			for(int j=0;j<2;j++)
				edges[i][j]=sc.nextInt();
		System.out.println(new ConnectedComponentsUF().countComponents(n,edges));
	}	
}

