/*
You are given an integer array height of length n. There are n vertical lines drawn such 
that the two endpoints of the ith line are (i, 0) and (i, height[i]).

Find two lines that together with the x-axis form a container, such that the container 
contains the most water.

Return the maximum amount of water a container can store.

Notice that you may not slant the container.

Example 1:
Input: height = [1,8,6,2,5,4,8,3,7]
Output: 49
Explanation: The above vertical lines are represented 
by array [1,8,6,2,5,4,8,3,7]. 
In this case, the max area of water (blue section) the container can contain is 49.

Example 2:

Input: height = [1,1]
Output: 1

*/
import java.util.*;
public class ContainerWMW 
{
    public static int maxArea(int[] height) 
	{
        int m = 0;
        int l = 0;
        int r = height.length - 1;

        while (l < r) 
		{
            m = Math.max(m, (r - l) * Math.min(height[l], height[r]));

            if (height[l] < height[r]) 
			{
                l++;
            } else {
                r--;
            }
        }

        return m;
    }
	public static void main(String[] args) 
	{
		Scanner s = new Scanner(System.in);

        int n = s.nextInt();

        int[] h = new int[n];

        for(int i = 0; i < n; i++) {
            h[i] = s.nextInt();
        }

		System.out.println(maxArea(h) );
	}
}

/*
Java Program to implement a Circular Queue
*/

import java.util.*;
class CQueue
{
	int cq[],f,r,size;
	CQueue(int size)
	{
		this.size=size;
		f=-1;
		r=-1;
		cq=new int[size];
	}
	void cqinsert(int x)
	{
		if((f==0&r==size-1)||(f==r+1))
		{
			System.out.println("Circular Queue is full");
			return;
		}
		if(r==size-1)
			r=0;
		else
			r++;
		cq[r]=x;
		if(f==-1)
			f=0;
	}
	int cqdelete()
	{
		if(f==-1)
		{
			System.out.println("Circular Queue is empty");
			return -1;
		}
		int x=cq[f];

		if(f==r)
			f=r=-1;
		else if(f==size-1)
			f=0;
		else
			f++;
		return x;
	}
	void cqdisplay()
	{
		if(f==-1)
		{
			System.out.println("Queue is empty");
			return;
		}
		int m=f,i;
		do
		{
			i=m%size;
			System.out.print(cq[i]+"	 ");
			m++;
		}while(i!=r);
		System.out.println();
	}

	boolean isEmpty()
	{
		return f==-1;
	}

	boolean isFull()
	{
		return (f==0&r==size-1)|(f==r+1);
	}
}
class CQueueDemo
{
	public static void main(String[] args) 
	{
		Scanner s=new Scanner(System.in);
		System.out.println("Enter the size");
		int size=s.nextInt();
		CQueue cq=new CQueue(size);
		while(true)
		{
			System.out.print("\n1.Qinsert ");
			System.out.print("2.Qdelete ");
			System.out.print("3.Qdisplay ");
			System.out.print("4.IsEmpty ");
			System.out.print("5.IsFull ");
			System.out.print("6.Exit\n");
			System.out.println("Enter choice");
			int ch=s.nextInt();
			switch(ch)
			{
				case 1:System.out.println("Enter the value");
