import java.util.*;
class DQueue
{
	int dq[],f,r,size;
	DQueue(int size)
	{
		this.size=size;
		f=-1;
		r=-1;
		dq=new int[size];
	}
	void insertRear(int x)
	{
		if(r==size-1)
		{
			System.out.println("DQueue is full");
			return;
		}
		r++;
		dq[r]=x;
		if(f==-1)
			f=0;
	}
	void insertFront(int x)
	{
		if(f==0)
		{
			System.out.println("DQueue is full");
			return;
		}
		if(f==-1)
			f=r=0;
		else
			f--;
		dq[f]=x;
	}
	int deleteRear()
	{
		if(r==-1)
		{
			System.out.println("DQueue is empty");
			return -1;
		}
		int x=dq[r];
		if(f==r)
			f=r=-1;
		else
			r--;
		return x;
	}

	int deleteFront()
	{
		if(f==-1)
		{
			System.out.println("Queue is empty");
			return -1;
		}
		int x=dq[f];
		if(f==r)
			f=r=-1;
		else
			f++;
		return x;
	}
	void qdisplay()
	{
		if(f==-1)
		{
			System.out.println("DQueue is empty");
			return;
		}
		for(int i=f;i<=r;i++)
		{
			System.out.print(dq[i]+"	 ");
		}
		System.out.println();
	}

	int qsize()
	{
		if(f==-1)
			return 0;
		else
			return r-f+1;
	}

	boolean isEmpty()
	{
		return f==-1;
	}

	boolean isFull()
	{
		return r==size-1;
	}
}
class DQueueDemo
