/*
Java Program to evaluate a postfix expression

Sample Input and Output:
input=56+7*
output=77

input=42*63/+5-
output=5
*/
import java.util.*;
class EvaluatePostfix
{
	char stack[];
	int top,size;
	EvaluatePostfix(int size)
	{
		this.size=size;
		top=-1;
		stack=new char[size]; 
	}

	void push(char ch)
	{
		top++;
		stack[top]=ch;
	}

	char pop()
	{
		char ch;
		ch=stack[top];
		top--;
		return ch;
	}
	int evaluate(String postfix)
	{
		char p[]=postfix.toCharArray();
		for(int i=0;i<p.length;i++)
		{
			if(p[i]>='0'&&p[i]<='9')
			{
				push((char)(p[i]-'0'));
			}
			else
			{
				int x=pop();
				int y=pop();
				switch(p[i])
				{
					case '+':push((char)(x+y));
								 break;
					case '-':push((char)(y-x));
								 break;
					case '*':push((char)(x*y));
								 break;
					case '/':push((char)(y/x));
								 break;
					case '%':push((char)(y%x));
								 break;

				}
			}
		}
		return pop();
	}
	public static void main(String[] args) 
	{
		Scanner s=new Scanner(System.in);
		String postfix=s.next();
		System.out.println(new EvaluatePostfix(20).evaluate(postfix));
	}
}

