/*
Program to find nth fibonacci number and 
count the number of ways to climb n steps

Sample Input and Output:
input=8
output=8 th fibonacci number is: 13
Number of ways to climb 8 steps is: 34

input=4
output=4 th fibonacci number is: 2
Number of ways to climb 4 steps is: 5

*/

import java.util.*;
class  FibSteps
{
	//Nth fibonacci number using recursion
	  public static int fib(int n) 
	  {
			if (n == 1) {
				return 0;
			}
			if (n == 2) {
				return 1;
			}
			return fib(n - 1) + fib(n - 2);
		}


	//Given n stairs, a person can climb either 1 or 2 steps at a time. 
	//Find the total number of ways to reach the top.
		public static int countWays(int n)
		{
			// Base cases
			if (n == 1) {
				return 1; 
			}
			if (n == 2) {
				return 2;
			}
			return countWays(n - 1) + countWays(n - 2);
		}

	public static void main(String[] args) 
	{
		Scanner s=new Scanner(System.in);
		int n=s.nextInt();
		System.out.println(n+" th fibonacci number is: "+fib(n));
		System.out.println("Number of ways to climb "+n+"steps is: "+countWays(n));
	}
}

