/*
Problem: Frequency Sort

Design a way to sort the list of positive integers in descending order according to the frequency of the 
elements.
Elements with higher frequency should come before those with lower frequency.
Elements with the same frequency should appear in the same order as they appear in the input list.

Input:
The first line contains an integer N  the number of elements in the list.
The second line contains N space-separated positive integers.

Output:
Print N space-separated integers representing the elements of the list sorted by frequency as 
described above.

Constraints:

1 <= N <= 10^5

1 <= element <= 10^9

Example:
Input:

19  
1 2 2 3 3 3 4 4 5 5 5 5 5 6 6 6 7 8 9 10

Output:
5 5 5 5 5 3 3 3 6 6 6 2 2 4 4 1 7 8 9 10

*/

import java.util.*;

public class FrSort {

    public static int[] freqSort(int[] list) 
	{
        Map<Integer, Integer> freqMap = new HashMap<>();
        Map<Integer, Integer> firstIndexMap = new HashMap<>();

        // Count frequencies and track first occurrence index
        for (int i = 0; i < list.length; i++) 
		{
            freqMap.put(list[i], freqMap.getOrDefault(list[i], 0) + 1);
            firstIndexMap.putIfAbsent(list[i], i);
        }

        // Convert to list of Integer for custom sorting
        List<Integer> sortedList = new ArrayList<>();
        for (int num : list) 
		{
            sortedList.add(num);
        }

        // Sort by frequency descending, then by original order
//        sortedList.sort((a, b) -> {
//            int freqCompare = Integer.compare(freqMap.get(b), freqMap.get(a));
//            if (freqCompare == 0) 
//			{
//                return Integer.compare(firstIndexMap.get(a), firstIndexMap.get(b));
//            }
//            return freqCompare;
//        });

		Collections.sort(sortedList, new Comparator<Integer>() 
		{
		public int compare(Integer a, Integer b) 
		{
			int freqCompare = Integer.compare(freqMap.get(b), freqMap.get(a)); // descending
			if (freqCompare == 0) 
			{
				return Integer.compare(firstIndexMap.get(a), firstIndexMap.get(b)); // ascending
			}
			return freqCompare;
		}
	    });

        // Convert result back to array
        int[] result = new int[list.length];
        for (int i = 0; i < list.length; i++) 
		{
            result[i] = sortedList.get(i);
        }
        return result;
    }

    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);

        int listSize = in.nextInt();
        int[] list = new int[listSize];
        for (int i = 0; i < listSize; i++) 
		{
            list[i] = in.nextInt();
        }

        int[] result = freqSort(list);
        for (int num : result) 
		{
            System.out.print(num + " ");
        }
    }
}

