import java.util.*;

public class GetMaximumGold {
    static int max = 0;

    public static void getMaxGold(int[][] a, int i, int j, boolean[][] visited, int currentGold) 
	{
        if (i < 0 || j < 0 || i >= a.length || j >= a[0].length || a[i][j] == 0 || visited[i][j]==true) 
		{
            return;
        }

        visited[i][j] = true;
        currentGold += a[i][j];
        max = Math.max(max, currentGold);

        // Explore all 4 directions
        getMaxGold(a, i - 1, j, visited, currentGold); // up
        getMaxGold(a, i + 1, j, visited, currentGold); // down
        getMaxGold(a, i, j - 1, visited, currentGold); // left
        getMaxGold(a, i, j + 1, visited, currentGold); // right

        visited[i][j] = false; // backtrack
    }

    public static void main(String args[]) {
        Scanner sc = new Scanner(System.in);
        int m = sc.nextInt();
        int n = sc.nextInt();

        int[][] a = new int[m][n];
        for (int i = 0; i < m; i++)
            for (int j = 0; j < n; j++)
                a[i][j] = sc.nextInt();

        boolean[][] visited = new boolean[m][n];

        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                if (a[i][j] != 0) {
                    getMaxGold(a, i, j, visited, 0);
                }
            }
        }

        System.out.println(max);
    }
}

