			case ')':return 0;
			default:return 5;
		}
	}

	int spriority(char ch)
	{
		switch(ch)
		{
			case '+':
			case '-':return 2;
			case '*':
			case '/':
			case '%':return 4;
			case '(':return 0;
			default:return 6;
		}
	}

	String convert(String infix)
	{
		int i=0;
		StringBuilder postfix=new StringBuilder();
		char infixarray[]=infix.toCharArray();

		while(top!=-1)
		{
			while(ipriority(infixarray[i])<spriority(stack[top]))
			{
				postfix.append(pop());
			}
			if(ipriority(infixarray[i])==spriority(stack[top]))
			{
				pop();
			}
			else
			{
				push(infixarray[i]);
			}
			i++;
		}
		return postfix.toString();
	}

	public static void main(String[] args) 
	{
		InfixToPostFix itop=new InfixToPostFix(20);
		Scanner s=new Scanner(System.in);
		String infix=s.next();
		String postfix=itop.convert(infix);
		System.out.println(postfix);
	}
}

