import java.util.*;
class KthSmallestSubarraySum 
{
    public int kthSmallestSubarraySum(int a[], int k)
     {
        int min = Integer.MAX_VALUE, sum = 0;
        for (int num : a) 
        {
            min = Math.min(min, num);
            sum += num;
        }
        int low = min, high = sum;
        while (low < high)
         {
            int mid = (low+high)/2;
            int count = countSubarrays(a, mid);
            if (count < k)
                low = mid + 1;
            else
                high = mid;
        }
        return low;
    }


    public int countSubarrays(int[] a, int threshold)
     {
        int count = 0;
        int sum = 0;
        int length = a.length;
        int left = 0, right = 0;
        while (right < length) 
        {
            sum += a[right];
            while (sum > threshold)
            {
                sum -= a[left];
                left++;
            }
            count += right - left + 1;
            right++;
        }
        return count;
    }
    public static void main(String[] args)
    {
