        int n=sc.nextInt();
		int array[]=new int[n];

          for(int i=0;i<n;i++)
          {
            array[i]=sc.nextInt();
          }

           int k=sc.nextInt();
       System.out.println(new KthSmallestSubarraySum().kthSmallestSubarraySum(array, k));
    }
}

