import java.util.*;
class BinaryTreeNode
{
	public int data; 
	public BinaryTreeNode left, right; 
	public BinaryTreeNode(int data)
	{
		this.data = data; 
		left = null; 
		right = null; 
	}
}

public class LargestValues
{
	static BinaryTreeNode root;
	void insert(BinaryTreeNode temp, int key)
    {

        if (temp == null) 
		{
            root = new BinaryTreeNode(key);
            return;
        }
        Queue<BinaryTreeNode> q = new LinkedList<BinaryTreeNode>();
        q.add(temp);

        // Do level order traversal until we find
        // an empty place.
        while (!q.isEmpty()) 
		{
            temp = q.peek();
            q.remove();

            if (temp.left == null) 
			{
                temp.left = new BinaryTreeNode(key);
                break;
            }
            else
                q.add(temp.left);

            if (temp.right == null) 
			{
                temp.right = new BinaryTreeNode(key);
                break;
            }
            else
                q.add(temp.right);
        }
    }
	List<Integer> largestValues(BinaryTreeNode root)
    {
        List<Integer> l = new ArrayList<>();
        if(root == null)
            return l;

        Queue<BinaryTreeNode> q = new LinkedList<>();
        q.offer(root);

        while(!q.isEmpty())
        {
            int size = q.size();
            int max = Integer.MIN_VALUE;
            for(int i=0;i<size;i++)
            {
                BinaryTreeNode p = q.poll();
                if(p.left!= null&&p.left.data!=-1)
                    q.offer(p.left);
                if(p.right!= null&&p.right.data!=-1)
                    q.offer(p.right);
                max = Math.max(max,p.data);   //Storing the max of each row...
            }
            l.add(max);
        }
        return l;
    }
	public static void main(String[] args) 
	{
		Scanner sc=new Scanner(System.in);
		String str[]=sc.nextLine().split(" ");
		LargestValues st=new LargestValues();
		root=new BinaryTreeNode(Integer.parseInt(str[0]));
		for(int i=1; i<str.length; i++)
			st.insert(root,Integer.parseInt(str[i]));
		System.out.println(st.largestValues(root));	
	}
}

/*
Given two strings text1 and text2 , return the length of their longest common subsequence.
A subsequence of a string is a new string generated from the original string with some characters
(can be none) deleted without changing the relative order of the remaining characters. 
(eg, "ace" is a subsequence of "abcde" while "aec" is not). 
A common subsequence of two strings is a subsequence that is common to both strings.

If there is no common subsequence, return 0.

Example 1:
Input:
abcde
ace
Output: 3
Explanation: The longest common subsequence is "ace" and its length is 3.
Example 2:
Input: 
abc
abc
Output: 3
Explanation: The longest common subsequence is "abc" and its length is 3.
Example 3:
Input: 
abc
def
Output: 0
Explanation: There is no such common subsequence, so the result is 0.
*/

import java.util.*;

class LCS 
{
    public static int longestCommonSubsequence(String text1, String text2) 
	{      
		int[][] dp = new int[text1.length()+1][text2.length()+1];
		int re=0;
        for(int i = 1; i<=text1.length(); i++)
		{
             for(int j = 1; j <=text2.length(); j++)
			{
                if(text1.charAt(i-1) == text2.charAt(j-1))
				{
                    dp[i][j] = dp[i-1][j-1]+1;
                }
				else
				{
                    dp[i][j]=Math.max(dp[i-1][j],dp[i][j-1]);
                }
                re=Math.max(dp[i][j],re);
            }
        }
        return re;
    }

	public static void main(String args[])
	{
		Scanner sc=new Scanner(System.in);
		String s1=sc.next();
		String s2=sc.next();
		System.out.println(longestCommonSubsequence(s1,s2));
	}
}



