/*
872. Leaf-Similar Trees

Consider all the leaves of a binary tree, from left to right order,
the values of those leaves form a leaf value sequence.

            3
           / \
          5   1
         / \  / \
        6  2  9  8
          / \
         7   4   

For example, in the given tree above, the leaf value sequence is (6, 7, 4, 9, 8).

Two binary trees are considered leaf-similar if their leaf value sequence 
is the same.

Return true if and only if the two given trees with head nodes 
root1 and root2 are leaf-similar.



Example 1:
            3                      3
           / \                    / \          
          5   1                 5   1
         / \  / \              / \  / \
        6  2  9  8          6  7 4  2
           / \                          / \
          7   4                       9  8 

Input: 
root1 = [3,5,1,6,2,9,8,null,null,7,4], 
root2 = [3,5,1,6,7,4,2,null,null,null,null,null,null,9,8]
Output: true

Example 2:
            1                      1
           / \                    / \          
          2   3                  3   2

Input: 
root1 = [1,2,3],  
root2 = [1,3,2]
Output: false


Sample Input and Output:

input= 1 2 3
1 3 2
output=
false

input= 3 5 1 6 2 9 8 -1 -1 7 4
3 5 1 6 7 4 2 -1 -1 -1 -1 -1 -1 9 8
output=
true
*/

import java.util.*;

class BinaryTreeNode{
	public int data; 
	public BinaryTreeNode left, right; 
	public BinaryTreeNode(int data){
		this.data = data; 
		left = null; 
		right = null; 
	}
}

class LeafSimilarTrees
{
	static BinaryTreeNode insert(BinaryTreeNode root, int key)
    {
        if (root == null) 
		{
            root = new BinaryTreeNode(key);
            return root;
        }
        Queue<BinaryTreeNode> q = new LinkedList<BinaryTreeNode>();
        BinaryTreeNode temp=root;
		q.add(temp);

        // Do level order traversal until we find an empty place.
        while (!q.isEmpty()) 
		{
            temp = q.peek();
            q.remove();

            if (temp.left == null) 
			{
                temp.left = new BinaryTreeNode(key);
                break;
            }
            else
                q.add(temp.left);

            if (temp.right == null) 
			{
                temp.right = new BinaryTreeNode(key);
                break;
            }
            else
                q.add(temp.right);
        }
		return root;
	}

    public static boolean leafSimilar(BinaryTreeNode root1, BinaryTreeNode root2) 
    {
        List<Integer> leafValues1 = new ArrayList<>();
        List<Integer> leafValues2 = new ArrayList<>();

        collectLeafValues(root1, leafValues1);
        collectLeafValues(root2, leafValues2);

        return leafValues1.equals(leafValues2);
    }

    private static void collectLeafValues(BinaryTreeNode root, List<Integer> leafValues) 
    {
        if (root == null||root.data==-1) {
            return;
        }
        if ((root.left == null||root.left.data==-1) && (root.right == null||root.right.data==-1)) 
        {
            leafValues.add(root.data);
        }
        collectLeafValues(root.left, leafValues);
        collectLeafValues(root.right, leafValues);
    }

	public static void main(String args[])
	{
		Scanner sc=new Scanner(System.in);
		String str1[]=sc.nextLine().split(" ");
		BinaryTreeNode root1=new BinaryTreeNode(Integer.parseInt(str1[0]));
		for(int i=1 ; i<str1.length; i++)
			insert(root1,Integer.parseInt(str1[i]));
		String str2[]=sc.nextLine().split(" ");
		BinaryTreeNode root2=new BinaryTreeNode(Integer.parseInt(str2[0]));
		for(int i=1 ; i<str2.length; i++)
			insert(root2,Integer.parseInt(str2[i]));
		System.out.println(leafSimilar(root1,root2));
	}
}

