            root = new BinaryTreeNode(key);
            return;
        }
        Queue<BinaryTreeNode> q = new LinkedList<BinaryTreeNode>();
        q.add(temp);

        // Do level order traversal until we find
        // an empty place.
        while (!q.isEmpty()) {
            temp = q.peek();
            q.remove();

            if (temp.left == null) {
                temp.left = new BinaryTreeNode(key);
                break;
            }
            else
                q.add(temp.left);

            if (temp.right == null) {
                temp.right = new BinaryTreeNode(key);
                break;
            }
            else
                q.add(temp.right);
        }
    }
	public List<Integer> leftSideView(BinaryTreeNode root) 
	{
        List<Integer> res = new ArrayList<Integer>();
        if(root==null){
            return res;
        }
        //bfs approach to iterate every level
        Queue<BinaryTreeNode> q = new LinkedList<>();
        q.add(root);
		while(!q.isEmpty()){
            // array to hold node values for current level
            List<Integer> cur = new ArrayList<Integer>();
            int size = q.size();
			for (int i=0; i<size; i++)
			{
                BinaryTreeNode temp = q.poll();
				cur.add(temp.data);
                if(temp.left!=null&&temp.left.data!=-1)
				{
                    q.add(temp.left);
                }
                if(temp.right!=null&&temp.right.data!=-1)
				{
                    q.add(temp.right);
                }
            }
            //take the rightmost(last) element of the cur list
			res.add(cur.get(0));
	    }
        return res;
    }
	public static void main(String args[])
	{
		Scanner sc=new Scanner(System.in);
		String str[]=sc.nextLine().split(" ");
		LeftSideView st=new LeftSideView();
		root=new BinaryTreeNode(Integer.parseInt(str[0]));
		for(int i=1; i<str.length; i++)
			st.insert(root,Integer.parseInt(str[i]));
		System.out.println(st.leftSideView(root));
	}
}

/*
17. Letter Combinations of a Phone Number
Given a string containing digits from 2-9 inclusive, return all possible letter combinations that the number could represent. Return the answer in any order.

A mapping of digits to letters (just like on the telephone buttons) is given below. Note that 1 does not map to any letters.
2-> "abc"
3-> "def"
4->"ghi"
5->"jkl"
6->"mno"
7->"pqrs"
8->"tuv"
9->"wxyz"

Example 1:

Input: 
23  //digits
Output: ["ad","ae","af","bd","be","bf","cd","ce","cf"]

Example 2:
Input: 
2
Output: ["a","b","c"]

*/
import java.util.*;
class LetterCombinations
{
    public List<String> letterCombinations(String digits) 
	{
        List<String> res = new ArrayList<>();

        if (digits == null || digits.length() == 0) 
		{
            return res;
        }

        Map<Character, String> digitToLetters = new HashMap<>();
        digitToLetters.put('2', "abc");
        digitToLetters.put('3', "def");
        digitToLetters.put('4', "ghi");
        digitToLetters.put('5', "jkl");
        digitToLetters.put('6', "mno");
        digitToLetters.put('7', "pqrs");
        digitToLetters.put('8', "tuv");
        digitToLetters.put('9', "wxyz");

        backtrack(digits, 0, new StringBuilder(), res, digitToLetters);

        return res;        
    }

    private void backtrack(String digits, int idx, StringBuilder comb, List<String> res, Map<Character, String> digitToLetters) 
	{
        if (idx == digits.length()) 
		{
            res.add(comb.toString());
            return;
        }

        String letters = digitToLetters.get(digits.charAt(idx));
        for (char letter : letters.toCharArray()) 
		{
            comb.append(letter);
            backtrack(digits, idx + 1, comb, res, digitToLetters);
            comb.deleteCharAt(comb.length() - 1);
        }
    }    
	public static void main(String[] args) 
	{
		Scanner sc=new Scanner(System.in);
		String s=sc.next();
		System.out.println(new LetterCombinations().letterCombinations(s));
	}
}

