Input: 
7
7 7 7 7 7 7 7
Output: 1

*/
import java.util.*;

class LIS 
{
    public static int lengthOfLIS(int[] nums)
    {
         if(nums.length == 0)
            return 0;
		 int[] dp = new int[nums.length];
         Arrays.fill(dp, 1);
		 int m=1;
		 for(int i=1;i<nums.length;i++)
		 {
			 for(int j=0;j<i;j++)
			 {
				 if(nums[i]>nums[j])
				 {
					 dp[i]=Math.max(dp[i],dp[j]+1);
				 }
			}
			m=Math.max(m,dp[i]);
		 }
		 return m;
	}
	public static void main(String[] args)
    {
   	 Scanner sc=new Scanner(System.in);
		int n=sc.nextInt();     
   		int ar[]=new int[n];
		for(int i=0;i<n;i++)
			ar[i]=sc.nextInt();
       System.out.println(lengthOfLIS(ar));
    }
}

