/*3341.q Find Minimum Time to Reach Last Room I

There is a dungeon with n x m rooms arranged as a grid.

You are given a 2D array moveTime of size n x m, where 
moveTime[i][j] represents the minimum time in seconds after which 
the room opens and can be moved to. You start from the room (0, 0) at 
time t = 0 and can move to an adjacent room. Moving between adjacent 
rooms takes exactly one second.

Return the minimum time to reach the room (n - 1, m - 1).

Two rooms are adjacent if they share a common wall, either horizontally 
or vertically.

Example 1:
Input: moveTime = [[0,4],[4,4]]
Output: 6
Explanation:
The minimum time required is 6 seconds.
At time t == 4, move from room (0, 0) to room (1, 0) in one second.
At time t == 5, move from room (1, 0) to room (1, 1) in one second.

Example 2:
Input: moveTime = [[0,0,0],[0,0,0]]
Output: 3
Explanation:
The minimum time required is 3 seconds.
At time t == 0, move from room (0, 0) to room (1, 0) in one second.
At time t == 1, move from room (1, 0) to room (1, 1) in one second.
At time t == 2, move from room (1, 1) to room (1, 2) in one second.

Example 3:
Input: moveTime = [[0,1],[1,2]]
Output: 3


 case=1
 input=
 2 2
 0 1
 1 2
 output=
 3

 case=2
 input=
2 3
0 0 0
0 0 0
output=
3

case=3
input=
2 2
0 4
4 4 
output=
6
 */
import java.util.*;

public class MinimumTime {

    // Helper class for priority queue
    static class Cell implements Comparable<Cell> 
	{
        int time, row, col;

        Cell(int time, int row, int col) 
		{
            this.time = time;
            this.row = row;
            this.col = col;
        }

        public int compareTo(Cell other) 
		{
            return this.time - other.time;
        }
    }

    public static int minTime(int[][] moveTime) 
	{
        int n = moveTime.length;
        int m = moveTime[0].length;
        int[][] minTime = new int[n][m];
        for (int[] row : minTime) 
		{
            Arrays.fill(row, Integer.MAX_VALUE);
        }

        PriorityQueue<Cell> pq = new PriorityQueue<>();
        pq.add(new Cell(0, 0, 0));  // Start at (0,0) at time 0
        minTime[0][0] = 0;

        int[][] dirs = {{0,1},{1,0},{0,-1},{-1,0}}; // Right, Down, Left, Up

        while (!pq.isEmpty())
		{
            Cell curr = pq.poll();
            int time = curr.time;
            int x = curr.row;
            int y = curr.col;

            if (x == n - 1 && y == m - 1) 
			{
                return time; // Reached destination
            }

            for (int[] dir : dirs) 
			{
                int nx = x + dir[0];
                int ny = y + dir[1];

                if (nx >= 0 && ny >= 0 && nx < n && ny < m) 
				{
                    int nextTime = Math.max(time + 1, moveTime[nx][ny]);
                    if (nextTime < minTime[nx][ny]) 
					{
                        minTime[nx][ny] = nextTime;
                        pq.offer(new Cell(nextTime, nx, ny));
                    }
                }
            }
        }

        return -1; // Should never reach here if goal is reachable
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        // Read dimensions
        int n = scanner.nextInt();
        int m = scanner.nextInt();

        // Read grid
        int[][] moveTime = new int[n][m];
        for (int i = 0; i < n; i++) 
		{
            for (int j = 0; j < m; j++) 
			{
                moveTime[i][j] = scanner.nextInt();
            }
        }

        // Compute and print result
        int result = minTime(moveTime);
        System.out.println(result);

        scanner.close();
    }
}

