import java.util.*;
class  MSS
{
	public static double maxSum(int a[],int n,int k)
	{
		int s=0;
		for(int i=0;i<k;i++)
		{
			s=s+a[i];
		}
		int ms=s;
		for(int i=k;i<n;i++)
		{
			s=s+a[i]-a[i-k];
			if(ms<s)
				ms=s;
		}
		return (double)ms/k;
	}
