//method performs a BFS to explore the island and build a string representation of its 
//shape. To build the string representation, we keep track of the relative positions of 
//each cell in the island with respect to the starting cell.
//After exploring the island, we add the shape string to a set. If we encounter 
//another island with the same shape, we don't add it to the set again because we 
//only count distinct islands.
//Finally, the method returns the size of the set, which is the number of distinct 
//islands in the matrix.
//In the main method, we create a sample matrix and call the numDistinctIslands 
//method to test our implementation.

import java.util.*;

public class NumberOfDistinctIslandsDFS 
{
	static int br=0,bc=0;
    public static int numDistinctIslands(int[][] a) 
	{
        if (a == null || a.length == 0 || a[0].length == 0) 
		{
            return 0;
        }

        Set<String> set = new HashSet<>(); // used to store the shapes of the islands
        int rows = a.length, cols = a[0].length;

        for (int i = 0; i < rows; i++) 
		{
            for (int j = 0; j < cols; j++) 
			{
                if (a[i][j] == 1) 
				{
					br=i;
					bc=j;
                    StringBuilder sb = new StringBuilder();
                    path(a,i,j,sb);
					set.add(sb.toString());
				}
			}
		}
		return set.size();
    }
	public static void path(int a[][],int row,int col,StringBuilder sb)
	{
		 if(row<0||col<0||row>=a.length||col>=a[0].length||a[row][col]==0)
			 return;
		 sb.append(row-br).append(col-bc).append(",");
		 a[row][col]=0;
		 path(a,row-1,col,sb);
		 path(a,row,col+1,sb);
		 path(a,row,col-1,sb);
		 path(a,row+1,col,sb);
	}

    public static void main(String[] args) 
	{
