import java.util.LinkedList;
import java.util.Queue;

public class NumberOfStudentsUnableToEatLunch 
{
    public int countStudents(int[] students, int[] sandwiches) 
	{
        Queue<Integer> studentQueue = new LinkedList<>();
        for (int s : students) 
		{
            studentQueue.offer(s);
        }

        int index = 0; // sandwich index
        int rotations = 0; // tracks number of students moved to end without success

        while (!studentQueue.isEmpty()) 
		{
            if (studentQueue.peek() == sandwiches[index]) 
			{
                studentQueue.poll(); // student eats
                index++; // move to next sandwich
                rotations = 0; // reset since one ate
            } 
			else 
			{
                studentQueue.offer(studentQueue.poll()); // move to end
                rotations++;
            }

            // If all students in current queue have rotated once with no one eating:
            if (rotations == studentQueue.size()) {
                break;
            }
        }

        return studentQueue.size(); // those who couldn't eat
    }

    public static void main(String[] args) {
        NumberOfStudentsUnableToEatLunch obj = new NumberOfStudentsUnableToEatLunch();

        int[] students1 = {1,1,0,0};
        int[] sandwiches1 = {0,1,0,1};
        System.out.println("Example 1 Output: " + obj.countStudents(students1, sandwiches1)); // Expected: 0

        int[] students2 = {1,1,1,0,0,1};
        int[] sandwiches2 = {1,0,0,0,1,1};
        System.out.println("Example 2 Output: " + obj.countStudents(students2, sandwiches2)); // Expected: 3
    }
}

