import java.util.*;

public class NumberofSubarraysofSizeKAverageGreaterthanorEqualtoThreshold
 {
    public int numOfSubarrays(int[] arr, int k, int threshold)
     {
        int n = arr.length;
        int res = 0;
        int sum = 0;

        // Calculate the sum of the first 'k' elements
        for (int i = 0; i < k; i++) 
        {
            sum += arr[i];
        }

        // Slide the window of size 'k' across the array
        for (int i = k; i < n; i++)
         {
            // If the average of the current window is >= threshold, increment result
            if (sum / k >= threshold) 
            {
                res++;
            }

            // Slide the window: subtract the element going out and add the incoming one
            sum -= arr[i - k];
            sum += arr[i];
        }

        // Check the last window after the loop
        if (sum / k >= threshold)
         {
            res++;
        }

        return res;
    }

    public static void main(String args[])
    {
        Scanner sc=new Scanner(System.in);

        int n=sc.nextInt();
         int a[]=new int[n];
          for(int i=0;i<n;i++)
          {
            a[i]=sc.nextInt();
          }
            int k=sc.nextInt();
            int t=sc.nextInt();

            System.out.println(new NumberofSubarraysofSizeKAverandageGreaterthanorEqualtoThreshold().numOfSubarrays(a,k,t));
    }
