import java.util.*;
class node
{
		int data;
		node next;
};

class LList
{
	node head;
	LList()
	{
		head=null;
	}

	void create(int x)
	{
		node nn,temp=head;

		nn=new node();
		nn.data=x;
		nn.next=null;

		if(head==null)
		{
			head=nn;
			return;
		}
		while(temp.next!=null)
			temp=temp.next;

		temp.next=nn;
	}

	void display()
	{
		node temp=head;
		while(temp!=null)
		{
			System.out.print(temp.data+" ");
			temp=temp.next;
		}
		System.out.println();
	}

	node left;

    public boolean isPalindrome() 
	{
        left = head;

        boolean result = check(head);
        return result;
    }

    public boolean check(node right)
	{

        //stop recursion
        if (right == null)
            return true;

        //if sub-list is not palindrome,  return false
        boolean x = check(right.next);
        if (!x)
            return false;

        //current left and right
        boolean y = (left.data == right.data);

        //move left to next
        left = left.next;

        return y;
    }
}

