/*
Mary is developing  an application on the concepts of prime numbers and factorization Among N 
numbers of the list displayed on the application display , the application will highlight all the numbers 
that appear as many times on the display as the frequency of their prime factors.

Write an algorithm to help Mary find all the numbers that appear as many times on the display as the 
frequency of their prime factors.

Input:
-------
The first line of the input consists of an integer num, representing the size of the list(N),
the second line consists of N space separated integers representing the numbers displayed on the application display.

Output:
-------
Print M space-separated integers representing all the numbers that appears as many times 
on the display as the frequency of their prime factors in ascending order. if no such number
is found in the given list then print -1.


Constraints
------------
0 < num <=10^5

0<= data <=10^6;where data represents a number on the display 

Example
-------
input:
7
4 2 12 25 12 12 25

output:
2 12 25

Explanation:
2 has 1 prime factor.
12 has 3 prime factors: 2,2,3
25 has 2 prime factors: 5,5.
2 is present one time , 12 is present 3 times, and 25 is present 2 times in the given list
so the output is [2,12,25]

*/
import java.util.*;

public class PrimeFactorFrequencyMatch 
{
    // Function to count total prime factors with multiplicity
    public static int countPrimeFactors(int n) 
	{
        if (n < 2) return 0; // 0 and 1 have no prime factors
        int count = 0;
        while (n % 2 == 0) 
		{
            count++;
            n /= 2;
        }
        for (int i = 3; i * i <= n; i += 2) 
		{
            while (n % i == 0) 
			{
                count++;
                n /= i;
            }
        }
        if (n > 2) 
			count++; // n itself is a prime
        return count;
    }

    public static void main(String[] args) 
	{
        Scanner sc = new Scanner(System.in);

        // Input
        int num = sc.nextInt();
        int[] arr = new int[num];
        Map<Integer, Integer> freqMap = new HashMap<>();

        for (int i = 0; i < num; i++) 
		{
            arr[i] = sc.nextInt();
            freqMap.put(arr[i], freqMap.getOrDefault(arr[i], 0) + 1);
        }

        List<Integer> result = new ArrayList<>();

        for (int number : freqMap.keySet()) 
		{
            int frequency = freqMap.get(number);
            int primeFactorCount = countPrimeFactors(number);

            if (frequency == primeFactorCount)
			{
                result.add(number);
            }
        }

        if (result.isEmpty()) 
		{
            System.out.println(-1);
        } 
		else 
		{
            Collections.sort(result);
            for (int val : result) 
			{
                System.out.print(val + " ");
            }
        }
    }
}

