import java.util.*;


import java.util.*;

class Node
 {
    int data;
    Node left, right;

    Node(int value)
     {
        this.data = value;
    }
}

class Solution 
{
    public final Node getTargetCopy(final Node original, final Node cloned, final Node target)
     {
        if (original == null) 
        return null;

        if (original == target) 
        return cloned;

        Node left = getTargetCopy(original.left, cloned.left, target);
        if (left != null) 
        return left;

        else
        {
        return getTargetCopy(original.right, cloned.right, target);
        }
    }
}

class Test
{
    public static void main(String[] args) 
    {
        Scanner sc = new Scanner(System.in);

        String[] arr = sc.nextLine().split(",");

        int targetValue = sc.nextInt();

        List<Integer> v = new ArrayList<>();
        for (String s : arr) 
        {
            v.add(Integer.parseInt(s));
        }

        Node originalRoot = buildTree(v);

        Node clonedRoot = cloneTree(originalRoot);

        Node targetNode = findNode(originalRoot, targetValue);

        if (targetNode == null)
         {
            System.out.println("Target node not found in the tree.");
            return;
        }

        Node result = new Solution().getTargetCopy(originalRoot, clonedRoot, targetNode);
        System.out.println(result.data);
    }

    // Build tree from level-order list
    private static Node buildTree(List<Integer> v) 
    {
        if (v == null || v.isEmpty() || v.get(0) == null) return null;

        Node root = new Node(v.get(0));
        Queue<Node> q = new LinkedList<>();
        q.add(root);

        int i = 1;
        while (i < v.size()) {
            Node current = q.poll();

            if (i < v.size() && v.get(i) != null) {
                current.left = new Node(v.get(i));
                q.add(current.left);
            }
            i++;

            if (i < v.size() && v.get(i) != null) {
                current.right = new Node(v.get(i));
                q.add(current.right);
            }
            i++;
        }

        return root;
    }

    // Clone the binary tree
    private static Node cloneTree(Node root)
     {
        if (root == null) return null;
        Node newNode = new Node(root.data);
        newNode.left = cloneTree(root.left);
        newNode.right = cloneTree(root.right);
        return newNode;
    }

    // Find node with given value
    private static Node findNode(Node root, int target) 
    {
        if (root == null) return null;

        if (root.data == target) return root;

        Node left = findNode(root.left, target);
        if (left != null) 
        return left;

        return findNode(root.right, target);
    }
}

