import java.util.*;

class BinaryTreeNode
{
	public int data; 
	public BinaryTreeNode left, right; 
	public BinaryTreeNode(int data)
	{
		this.data = data; 
		left = null; 
		right = null; 
	}
}

class RangeSum
{
	static BinaryTreeNode insert(BinaryTreeNode root, int key)
    {
        if (root == null) 
		{
            root = new BinaryTreeNode(key);
            return root;
        }
        Queue<BinaryTreeNode> q = new LinkedList<BinaryTreeNode>();
        BinaryTreeNode temp=root;
		q.add(temp);

        // Do level order traversal until we find an empty place.
        while (!q.isEmpty()) 
		{
            temp = q.peek();
            q.remove();

            if (temp.left == null) 
			{
                temp.left = new BinaryTreeNode(key);
                break;
            }
            else
                q.add(temp.left);

            if (temp.right == null) 
			{
                temp.right = new BinaryTreeNode(key);
                break;
            }
            else
                q.add(temp.right);
        }
		return root;
	}
    public static int rangeSumBST(BinaryTreeNode root, int low, int high)
    {
        if (root == null||root.data==-1) 
		{
            return 0;
        }

        int currentVal = (root.data >= low && root.data <= high) ? root.data : 0;

        int leftSum = rangeSumBST(root.left, low, high);
        int rightSum = rangeSumBST(root.right, low, high);

        return currentVal + leftSum + rightSum;
    }
	public static void main(String args[])
	{
		Scanner sc=new Scanner(System.in);
		String str1[]=sc.nextLine().split(" ");
		BinaryTreeNode root=new BinaryTreeNode(Integer.parseInt(str1[0]));
		for(int i=1 ; i<str1.length; i++)
			insert(root,Integer.parseInt(str1[i]));
		int low=sc.nextInt();
		int high=sc.nextInt();
		System.out.println(rangeSumBST(root,low,high));

	}
}

