public static int binaryToDecimal(int n, int power) {
        // Base case: if the number becomes 0, return 0
        if (n == 0) {
            return 0;
        }
        // Recursive case: extract the last digit and process the remaining number
        return (n % 10) * (int) Math.pow(2, power) + binaryToDecimal(n / 10, power + 1);
