// Recursive function to find the maximum element in the array
    public static int findMax(int[] arr, int index) {
        // Base case: if we reach the last element, return it
        if (index == arr.length - 1) {
            return arr[index];
        }

        // Recursive case: get the maximum of the rest of the array
        int maxInRest = findMax(arr, index + 1);

        // Return the maximum between the current element and the max of the rest
        return Math.max(arr[index], maxInRest);
    }
