// Recursive function to generate permutations
    public static void generatePermutations(String str, String permutation) {
        // Base case: if the input string is empty, print the permutation
        if (str.isEmpty()) {
            System.out.println(permutation);
            return;
        }

        // Loop through each character and generate permutations
        for (int i = 0; i < str.length(); i++) {
            // Pick the character at index i
            char currentChar = str.charAt(i);
            // Form the remaining string after removing the character at index i
            String remainingStr = str.substring(0, i) + str.substring(i + 1);
            // Recursively generate permutations with the remaining string
            generatePermutations(remainingStr, permutation + currentChar);
        }
    }

