// Recursive function to generate all subsets
    public static void generateSubsets(int[] arr, int index, List<Integer> currentSubset) {
        // Base case: If we've processed all elements, print the subset
        if (index == arr.length) {
            System.out.println(currentSubset);
            return;
        }

        // Exclude the current element and recurse
        generateSubsets(arr, index + 1, currentSubset);

        // Include the current element and recurse
        currentSubset.add(arr[index]);
        generateSubsets(arr, index + 1, currentSubset);

        // Backtrack: Remove the last element before returning to the previous state
        currentSubset.remove(currentSubset.size() - 1);
    }

