//Implement a recursive function to check if an array is sorted in non-decreasing order.

    public static boolean isSorted(int[] arr, int index) {
        // Base case: If we have reached the last element or empty array
        if (index == arr.length - 1 || arr.length == 0) {
            return true;
        }
        // If the current element is greater than the next one, return false
        if (arr[index] > arr[index + 1]) {
            return false;
        }
        // Recursively check for the next element
        return isSorted(arr, index + 1);
    }

