        int[] arr = {1, 2, 3, 4, 5}; // Sorted array
        int[] arr2 = {1, 3, 2, 4, 5}; // Unsorted array

        System.out.println("Array 1 is sorted: " + isSorted(arr, 0));
        System.out.println("Array 2 is sorted: " + isSorted(arr2, 0));
    }

// Given a string, remove duplicate characters using recursion.
public static String removeDuplicates(String str, int index, HashSet<Character> seen) {
        // Base case: If we have processed the entire string
        if (index == str.length()) {
            return "";
        }

        char currentChar = str.charAt(index);

        // If the character is not seen, include it and mark it as seen
        if (!seen.contains(currentChar)) {
            seen.add(currentChar);
            return currentChar + removeDuplicates(str, index + 1, seen);
        }

        // If the character is already seen, skip it
        return removeDuplicates(str, index + 1, seen);
    }

    public static void main(String[] args) {
        String input = "banana";
        HashSet<Character> seen = new HashSet<>();
        String result = removeDuplicates(input, 0, seen);
        System.out.println("String after removing duplicates: " + result);
    }

