//Binary Search using recursion

public static int binarySearch(int[] arr, int left, int right, int target) {
        // Base case: If the range is invalid, the element is not found
        if (left > right) {
            return -1;
        }

        int mid = left + (right - left) / 2;

        // If the middle element is the target, return its index
        if (arr[mid] == target) {
            return mid;
        }

        // If the target is smaller, search in the left half
        if (arr[mid] > target) {
            return binarySearch(arr, left, mid - 1, target);
        }

        // Otherwise, search in the right half
        return binarySearch(arr, mid + 1, right, target);
    }


// Recursive function for linear search
    public static int linearSearch(int[] arr, int index, int target) {
        // Base case: If index reaches the end of the array, return -1 (not found)
        if (index == arr.length) {
            return -1;
        }

        // If the current element matches the target, return the index
        if (arr[index] == target) {
            return index;
        }

        // Recursively search in the rest of the array
        return linearSearch(arr, index + 1, target);
    }

