import java.util.*;
class node
{
		int data;
		node next;
}

class LList
{
	node head;
	LList()
	{
		head=null;
	}

	void create(int x)
	{
		node nn,temp=head;

		nn=new node();
		nn.data=x;
		nn.next=null;

		if(head==null)
		{
			head=nn;
			return;
		}
		while(temp.next!=null)
			temp=temp.next;

		temp.next=nn;
	}

	void display()
	{
		node temp=head;
		while(temp!=null)
		{
			System.out.print(temp.data+" ");
			temp=temp.next;
		}
		System.out.println();
	}
    public void removeNthFromEnd(int n) 
	{
        node fp = head, sp = head;
        for (int i = 0; i < n; i++) 
			fp = fp.next;
        if (fp == null) 
		{
			head=head.next;
		}
        while (fp.next != null) 
		{
            fp = fp.next;
            sp = sp.next;
        }
        sp.next = sp.next.next;
     }
}

