import java.util.*;
class RemovetheParenthesis
{
    static int count(String s)
    {
        Stack<Character> st=new Stack<Character>();
        int ct=0;
    	for(int i=0;i<s.length();i++)
    	{
    		if(s.charAt(i)==')')
    		{
    			if(st.empty())
    			{
    				ct++;
    			}
    			else
    			{
    				st.pop();
    			}
    			continue;
    		}
    		st.push(s.charAt(i));
    	}
    	while(!st.empty())
    	{
    		st.pop();
    		ct++;
    	}
    	return ct;
    }
