import java.util.*;
class ReverseEveryWord
{
static String reverseEveryWord(String s)
{
    Stack<Character> st=new Stack<Character>();
    StringBuilder rs=new StringBuilder(); 
    for(int i = 0;i<s.length();i++)
	{
        if (s.charAt(i) != ' ')
		{
            st.push(s.charAt(i));
		} 
        else
		{
            while (st.empty() == false)
			{
                rs.append(st.pop());

            }
            rs.append(" ");
        }
    }
    //last word
	while (st.empty() == false)
	{
        rs.append(st.pop());
    }
	return new String(rs);
}

