Move disk 1 from s to d
*/
import java.util.*;

class  RGPGSTH
{
	public static String reverseString(String str) 
	{
        // Base case: if the string is empty or has one character, return it
        if (str.isEmpty())
		{
            return str;
        }
        // Recursive case: take the last character and append it to the reversed substring
        return reverseString(str.substring(1)) + str.charAt(0);
    }

	public static void generatePermutations(String str, String permutation) 
	{
        // Base case: if the input string is empty, print the permutation
        if (str.isEmpty()) 
		{
            System.out.println(permutation);
            return;
        }

        // Loop through each character and generate permutations
        for (int i = 0; i < str.length(); i++) 
		{
            // Pick the character at index i
            char currentChar = str.charAt(i);
            // Form the remaining string after removing the character at index i
            String remainingStr = str.substring(0, i) + str.substring(i + 1);
            // Recursively generate permutations with the remaining string
            generatePermutations(remainingStr, permutation + currentChar);
        }
    }

	// Recursive function to solve Tower of Hanoi
    public static void solveHanoi(int n, char source, char auxiliary, char destination) 
	{
 		if(n>0)
		{
			// Step 1: Move n-1 disks from source to auxiliary using destination
			solveHanoi(n - 1, source, destination, auxiliary);

			// Step 2: Move the nth (largest) disk from source to destination
			System.out.println("Move disk " + n + " from " + source + " to " + destination);

			// Step 3: Move n-1 disks from auxiliary to destination using source
			solveHanoi(n - 1, auxiliary, source, destination);
		}
	}
    public static void printSubsequences(int index, String str, String output)
	{
        // Base case: If we reach the end of the string, print the output
        if (index == str.length()) 
		{
            System.out.println(output);
            return;
        }
		// Include the current character and move to the next index
        printSubsequences(index + 1, str, output + str.charAt(index));

        // Exclude the current character and move to the next index
        printSubsequences(index + 1, str, output);


    }
	public static void main(String[] args) 
	{
		Scanner s=new Scanner(System.in);
		String str=s.next();
		int n=s.nextInt();
		System.out.println("Reverse is");
		System.out.println(reverseString(str));
		System.out.println("Permutations are");
		generatePermutations(str, "");
		System.out.println("Subseauqnces are");
		printSubsequences(0,str,"");
		System.out.println("Towers of Hanoi");
		solveHanoi(n,'s','i','d');
	}
}

