output =[1, 3, 6, 15]

case =8
input =1 2 3 4 5 6 7 15 14 13 12 10 11 9 7
output =[1, 3, 7, 7]

*/

import java.util.*;

class BinaryTreeNode{
	public int data; 
	public BinaryTreeNode left, right; 
	public BinaryTreeNode(int data)
	{
		this.data = data; 
		left = null; 
		right = null; 
	}
}
public class RightSideView
{
	static BinaryTreeNode root;
	void insert(BinaryTreeNode temp, int key)
    {

        if (temp == null) {
            root = new BinaryTreeNode(key);
            return;
        }
        Queue<BinaryTreeNode> q = new LinkedList<BinaryTreeNode>();
        q.add(temp);

        // Do level order traversal until we find
        // an empty place.
        while (!q.isEmpty()) {
            temp = q.peek();
            q.remove();

            if (temp.left == null) {
                temp.left = new BinaryTreeNode(key);
                break;
            }
            else
                q.add(temp.left);

            if (temp.right == null) {
                temp.right = new BinaryTreeNode(key);
                break;
            }
            else
                q.add(temp.right);
        }
    }

	public List<Integer> rightSideView(BinaryTreeNode root) 
	{
        List<Integer> res = new ArrayList<Integer>();
        if(root==null){
            return res;
        }
        //bfs approach to iterate every level
        Queue<BinaryTreeNode> q = new LinkedList<BinaryTreeNode>();
        q.add(root);
        while(!q.isEmpty()){
            // array to hold node values for current level
            List<Integer> cur = new ArrayList<Integer>();
            int size = q.size();
            for (int i=0; i<size; i++)
			{
                BinaryTreeNode temp = q.poll();
                cur.add(temp.data);
                if(temp.left!=null&&temp.left.data!=-1)
				{
                    q.add(temp.left);
                }
                if(temp.right!=null&&temp.right.data!=-1)
				{
                    q.add(temp.right);
                }
            }
            //take the rightmost(last) element of the cur list
            res.add(cur.get(cur.size()-1));
        }
        return res;
    }
	public static void main(String args[])
	{
		Scanner sc=new Scanner(System.in);
		String str[]=sc.nextLine().split(" ");
		RightSideView st=new RightSideView();
		root=new BinaryTreeNode(Integer.parseInt(str[0]));
		for(int i=1; i<str.length; i++)
			st.insert(root,Integer.parseInt(str[i]));
		System.out.println(st.rightSideView(root));
	}
}

