import java.util.*;
class  SBLPRP
{
	public static int sumOfDigits(int n) 
	{
			if (n == 0) {
				return 0;
			}
			return (n % 10) + sumOfDigits(n / 10);
		}

	public static int binaryToDecimal(int n, int power) 
	{
		if (n == 0) 
		{
			return 0;
		}
		return (n % 10) * (int) Math.pow(2, power) + binaryToDecimal(n / 10, power + 1);
	}

	public static int lcm(int a, int b, int multiple)
	{
		if (multiple % a == 0 && multiple % b == 0) {
			return multiple;
		}
		return lcm(a, b, multiple + 1);
	}


	 public static boolean isPrime(int n, int i) 
	 {
        // Base cases
        if (n <= 1) 
		{
            return false;  // Numbers less than or equal to 1 are not prime
        }
        if (i == n) 
		{
            return true;  // If we reach n, then n is prime
        }
        // If n is divisible by i, it's not prime
        if (n % i == 0) 
		{
            return false;
        }
        // Recursive case: check for next i
        return isPrime(n, i + 1);
    }


	   public static int reverse(int num, int rev) {
        if (num == 0) {
            return rev;
        }
        return reverse(num / 10, rev * 10 + num % 10);
    }


	public static double power(double x, int y) {
        // Base case: x^0 = 1
        if (y == 0) {
            return 1;
        }
        // Recursive case: x^y = x * x^(y-1)
        return x * power(x, y - 1);
    }

	public static void main(String[] args) 
	{
		Scanner s=new Scanner(System.in);
		int n1=s.nextInt();
		System.out.println(sumOfDigits(n1));
		int bn=s.nextInt();
		System.out.println(binaryToDecimal(bn,0));
		int num1=s.nextInt();
		int num2=s.nextInt();
		System.out.println(lcm(num1, num2, Math.max(num1, num2)));
		int n2=s.nextInt();
		System.out.println(isPrime(n2, 2));
		int n3=s.nextInt();
		System.out.println(reverse(n3, 0));
		double x=s.nextDouble();
		int y=s.nextInt();
		System.out.println(power(x,y));

	}
}

