/*
In a remote colony, n crew members are numbered from 1 to n.
A rumor says that one of them is the secret commander who issues the 
final orders behind the scenes.

If the commander exists, then by definition  all three of the following 
are true:

The commander never takes orders from anyone.

Every other crew member takes orders from (i.e., "trusts") the commander.

Exactly one person satisfies rules 1 and 2.

You are given an array orders where orders[i] = [ai, bi] means crew 
member ai takes orders from crew member bi.
If a pair is missing from the list, that ordering relationship does not exist.

Write a java program that returns the label of the secret commander if they 
can be uniquely identified, or 1 otherwise.

Example 1:
Input: n = 2, trust = [[1,2]]
Output: 2

Example 2:
Input: n = 3, trust = [[1,3],[2,3]]
Output: 3

Example 3:
Input: n = 3, trust = [[1,3],[2,3],[3,1]]
Output: -1

Sample Input and Output:

input=
3   // number of vertices
2 //number of edges
1 3 
2 3
output=
3

input=
3
3
1 3
2 3
3 1
output=
-1

*/

import java.util.*;

public class SecretCommanderUF 
{
     static int[] parent, size;

     SecretCommanderUF(int n)
	 {
            parent = new int[n + 1];
            size   = new int[n + 1];
            for (int i = 1; i <= n; i++) 
		   {
				parent[i] = -1;
				size[i]=1;
           }
	 }
     static int find(int x) 
	 {
		 while(parent[x]>=0)
		 {
			 x=parent[x];
		 }
		 return x;
	 }

	 static void union(int x, int y) 
	 {
            int p1 = find(x);
            int p2 = find(y);
            if (p1 != p2) 
			{
                if (size[p1] < size[p2]) 
				{ // Merge small size to large size
                    size[p2] += size[p1];
                    parent[p1] = p2;
                } 
				else 
				{
                    size[p1] += size[p2];
                    parent[p2] = p1;
                }
            }
        }     

    /** Returns commander's label or -1. */
    public static int findCommander(int n, int[][] orders) 
	{
        if (n == 1) return 1;      // single person is trivially commander

        int[] in  = new int[n + 1];
        int[] out = new int[n + 1];

        // Build DSU + degree counts
        for (int[] edge : orders) 
		{
            int a = edge[0], b = edge[1];
            if (a == b) continue;      // ignore self loops
            union(a, b);                  // a belongs to b's set
            out[a]++;
            in[b]++;
        }

        // Candidate must have indegree n-1 & outdegree 0
        int candidate = -1;
        for (int p = 1; p <= n; p++) 
		{
            if (in[p] == n - 1 && out[p] == 0) 
			{
                candidate = p;
                break;
            }
        }
        if (candidate == -1) 
		  return -1;

        // Ensure everyone is in candidate's component
        int root = find(candidate);
        for (int i = 1; i <= n; i++) 
		{
            if (find(i) != root) 
				return -1;
        }
        return candidate;
    }
    public static void main(String[] args) 
	{
        Scanner fs = new Scanner(System.in);
        int n = fs.nextInt();
		SecretCommanderUF sf=new SecretCommanderUF(n);
        int m = fs.nextInt();
        int[][] edges = new int[m][2];
        for (int i = 0; i < m; i++) 
		{
            edges[i][0] = fs.nextInt();
            edges[i][1] = fs.nextInt();
