import java.util.*;
class SLL
{
	class node
	{
		int data;
		node next;
	}
	node head;
	SLL()
	{
		head=null;
	}
	void create(int x)
	{
		node nn=new node();
		nn.data=x;
		nn.next=null;
		if(head==null)
		{
			head=nn;
			return;
		}
		node temp=head;
		while(temp.next!=null)
		{
			temp=temp.next;
		}
		temp.next=nn;
	}
	void display()
	{
		node temp=head;
		while(temp!=null)
		{
			System.out.print(temp.data+" ");
			temp=temp.next;
		}
	}
}
