import java.util.*;
class SmallestSubWithSumSlidingWindow
{
    static int smallestSubWithSum(int arr[], int n, int x)
    {

        int curr_sum = 0, min_len = n + 1;

        int start = 0, end = 0;
        while (end < n) {

            while (curr_sum <= x && end < n)
                curr_sum += arr[end++];

            while (curr_sum > x && start < n) {
                if (end - start < min_len)
                    min_len = end - start;

                curr_sum -= arr[start++];
            }
        }
        return min_len;
    }


    public static void main(String[] args)
    {
        Scanner s = new Scanner(System.in);

        int n = s.nextInt();

        int[] a = new int[n];

        for(int i = 0; i < n; i++) {
            a[i] = s.nextInt();
        }

        int k = s.nextInt();

		int res = smallestSubWithSum(a, n, k);
        if (res == n+1)
           System.out.println("Not Possible");
        else
           System.out.println(res);

    }
}
