import java.util.*;
class Stackk
{
	int size,top;
	int s[];
	Stackk(int size)
	{
		this.size=size;
		top=-1;
		s=new int[size];
	}

	void push(int x)
	{
		if(top==size-1)
		{
			System.out.println("Stack overflow");
			return;
		}
		top++;
		s[top]=x;
	}

	int pop()
	{
		if(top==-1)
		{
			return -1;
		}

//		int x=s[top];
//		top--;
//		return x;

		return s[top--];
	}

	void display()
	{
		if(top==-1)
		{
			System.out.println("Stack is empty");
			return;
		}

		for(int i=top;i>=0;i--)
		{
			System.out.print(s[i]+"	");
		}
		System.out.println();
	}

	int peek()
	{
		return top!=-1?s[top]:-1;
	}
}
class StackDemo
{
	public static void main(String[] args) 
	{
		Scanner s=new Scanner(System.in);
		Stackk sk=new Stackk(5);
		while(true)
		{
			System.out.println("\n1.push");
			System.out.println("2.pop");
			System.out.println("3.display");
			System.out.println("4.peek");
			System.out.println("5.exit");
			System.out.println("Enter choice");
			int ch=s.nextInt();
			switch(ch)
			{
				case 1:System.out.println("Enter a value");
							int x=s.nextInt();
							sk.push(x);
							break;
				case 2:int m=sk.pop();
							if(m!=-1)
							System.out.println("Popped value is "+m);
							else
							System.out.println("Stack is empty");
							break;
				case 3:sk.display();
							break;
				case 4:System.out.println(sk.peek());
							break;
				case 5:System.exit(0);
							break;
			}
		}
	}
}

/*
Problem: Street Light Fault Simulation
Woods, an electrician for Timberland city, has made some faulty connections on eight street lights. 
The errors cause a street light to go OFF if the adjacent lights (left and right) were either both ON (1)
or both OFF (0) on the previous day. Otherwise, the light will go ON as normal.

The two lights at the ends of the road have only a single adjacent street light, so the light at the end 
can be assumed to be always OFF on one side.

The state of the lights on a particular day is considered for the next day, not for the same day.

Input:
A list of 8 integers (0 or 1) representing the current state of street lights.

An integer M, representing the number of days to simulate.

Output:
Return the final state of the 8 street lights after simulating M days.

Constraints:
The list will always have 8 elements.

1 = M = 1000

Each light state is either 0 (OFF) or 1 (ON)

Example:
Input:
1 1 1 0 1 1 1 1   //input as list
2  //number of days
Output:
[0, 0, 0, 0, 0, 1, 1, 0]
*/

import java.util.*;

public class StreetLightSimulation 
{

    public static List<Integer> streetLight(List<Integer> currentState, int days) 
	{
        int n = currentState.size();
        //List<Integer> nextState = new ArrayList<>(currentState);

        for (int d = 0; d < days; d++) 
		{
            List<Integer> temp = new ArrayList<>(Collections.nCopies(n, 0));
            for (int i = 0; i < n; i++) 
			{
                int left = (i == 0) ? 0 : currentState.get(i - 1);
                int right = (i == n - 1) ? 0 : currentState.get(i + 1);

                if ((left == 1 && right == 1) || (left == 0 && right == 0)) {
                    temp.set(i, 0); // Light goes OFF
                } 
				else 
				{
                    temp.set(i, 1); // Light stays ON
                }
            }
            currentState = temp;
        }

        return currentState;
    }

    public static void main(String[] args) 
	{
        Scanner sc = new Scanner(System.in);
        List<Integer> currentState = new ArrayList<>();

        // Input current state of 8 lights
        for (int i = 0; i < 8; i++) 
		{
            currentState.add(sc.nextInt());
        }

        // Input number of days to simulate
        int days = sc.nextInt();

        List<Integer> result = streetLight(currentState, days);

		System.out.println(result);
    }
}

