            {
                Scanner sc=new Scanner(System.in);
                String s=sc.next();
                int k=sc.nextInt();
                System.out.println(hasAllCodes(s,k));
            }

}

import java.util.*;
class  SubArraySum
{
	public static int[] subArraySum(int a[],int n,int k)
	{
		int ans[]=new int[n-k+1];
		int s=0,p=0;
		for(int i=0;i<k;i++)
		{
			s=s+a[i];
		}
		ans[p++]=s;

		for(int i=k;i<n;i++)
		{
			s=s+a[i]-a[i-k];
			ans[p++]=s;
		}
		return ans;
	}
	public static void main(String[] args) 
	{
		Scanner s = new Scanner(System.in);

        int n = s.nextInt();

        int[] a = new int[n];

        for(int i = 0; i < n; i++) {
            a[i] = s.nextInt();
        }

        int k = s.nextInt();


        int[] ans  = subArraySum(a, n, k);
        for(int i = 0; i < ans.length; i++) {
            System.out.print(ans[i] + " ");
        }    
        System.out.println();
    }
}

