*/

import java.util.*;
class Subsets
{
    List<List<Integer>> Ans = new ArrayList<>();
    static int n;

    public List<List<Integer>> subsets(int[] nums) 
	{
        List<Integer> op = new ArrayList<>();
       // n = nums.length;
        // call the helper function
        subsetFinder(op, nums, 0);
        return Ans;
    }
    public void subsetFinder(List<Integer> op, int[] nums, int startIndex) 
	{
        // base case
        if (startIndex == n) 
		{
            Ans.add(new ArrayList<>(op));
            return;
        }

        // recursive case
        // choice 1: include the current element
        op.add(nums[startIndex]);
        subsetFinder(op, nums, startIndex + 1);

        // backtracking step
        op.remove(op.size() - 1);

        // choice 2: exclude the current element
        subsetFinder(op, nums, startIndex + 1);
    }

	public static void main(String args[])
	{
		Scanner sc=new Scanner(System.in);
		n=sc.nextInt();
		int arr[]=new int[n];
		for(int i=0;i<n;i++)
			arr[i]=sc.nextInt();
		System.out.println(new Subsets().subsets(arr));
	}
}

