/*
Given a non-empty string s and an abbreviation abbr , return whether
the string matches with the given abbreviation.
A string such as "word" contains only the following valid abbreviations:
["word", "1ord", "w1rd", "wo1d", "wor1", "2rd", "w2d", "wo2", "1o1d", 
"1or1", "w1r1", "1o2", "2r1","3d", "w3", "4"]
Notice that only the above abbreviations are valid abbreviations of the 
string "word" . Any other string is not a valid abbreviation of "word" .
Note:
Assume s contains only lowercase letters and abbr contains only 
lowercase letters and digits.

Example 1:
Input:
internationalization
i12iz4n
Output:true.

Example 2:
Input:
apple
a2e
Output:false.
*/
import java.util.*;

class ValidAbbreviation 
{
    public static boolean validity(String word, String abbr) 
	{
		int i=0,j=0;
		if(word==null||abbr==null)
			return false;
		while(i<word.length()&&j<abbr.length())
		{
			if(Character.isDigit(abbr.charAt(j)))
			{
				if(abbr.charAt(j)=='0')
					return false;

				int t=0;
				while(j<abbr.length()&&Character.isDigit(abbr.charAt(j)))
				{
					t=t*10+abbr.charAt(j)-'0';
					j++;
				}
				i+=t;
			}
			else
			{
				if(word.charAt(i)!=abbr.charAt(j))
					return false;
				i++;
				j++;
			}
		}
		return i==word.length()&&j==abbr.length();
    }

	public static void main(String args[])
	{
		Scanner sc=new Scanner(System.in);
		String word=sc.next();
		String abbr=sc.next();
		System.out.println(validity(word,abbr));
	}
}
