/*
Given a non-empty string s and an abbreviation abbr , return whether
the string matches with the given abbreviation.
A string such as "word" contains only the following valid abbreviations:
["word", "1ord", "w1rd", "wo1d", "wor1", "2rd", "w2d", "wo2", "1o1d", 
"1or1", "w1r1", "1o2", "2r1","3d", "w3", "4"]
Notice that only the above abbreviations are valid abbreviations of the 
string "word" . Any other string is not a valid abbreviation of "word" .
Note:
Assume s contains only lowercase letters and abbr contains only 
lowercase letters and digits.

Example 1:
Input:
internationalization
i12iz4n
Output:true.

Example 2:
Input:
apple
a2e
Output:false.
*/
import java.util.*;
public class WordAbbreviationDP 
{
    public static boolean validWordAbbreviation(String word, String abbr) 
	{
        int m = word.length();
        int n = abbr.length();
        boolean[][] dp = new boolean[m + 1][n + 1];

        dp[0][0] = true;

        for (int i = 0; i <= m; i++) 
		{
            for (int j = 0; j < n; j++) 
			{
                if (!dp[i][j]) continue;

                // Case 1: Match letter
                if (i < m && Character.isLetter(abbr.charAt(j)) && word.charAt(i) == abbr.charAt(j)) 
				{
                    dp[i + 1][j + 1] = true;
                }

                // Case 2: Abbreviation with digits (not starting with '0')
                if (Character.isDigit(abbr.charAt(j)) && abbr.charAt(j) != '0') 
				{
                    int num = 0;
                    for (int k = j; k < n && Character.isDigit(abbr.charAt(k)); k++) 
					{
                        num = num * 10 + (abbr.charAt(k) - '0');
                        if (i + num <= m) 
						{
                            dp[i + num][k + 1] = true;
                        } 
						else 
						{
                            break;
                        }
                    }
                }
            }
        }

        return dp[m][n];
    }

    public static void main(String[] args) 
	{
        Scanner sc=new Scanner(System.in);
		String word=sc.next();
		String abbr=sc.next();
        System.out.println(validWordAbbreviation(word,abbr)); 
    }
}
