*/
import java.util.*;
class BinaryTreeNode
{
	public int data; 
	public BinaryTreeNode left, right; 
	public BinaryTreeNode(int data)
	{
		this.data = data; 
		left = null; 
		right = null; 
	}
}

class  ZigZagOrder
{
	static BinaryTreeNode root;
	void insert(BinaryTreeNode temp, int key)
    {

        if (temp == null) 
		{
            root = new BinaryTreeNode(key);
            return;
        }
        Queue<BinaryTreeNode> q = new LinkedList<BinaryTreeNode>();
        q.add(temp);

        // Do level order traversal until we find
        // an empty place.
        while (!q.isEmpty()) 
		{
            temp = q.peek();
            q.remove();

            if (temp.left == null) 
			{
                temp.left = new BinaryTreeNode(key);
                break;
            }
            else
                q.add(temp.left);

            if (temp.right == null) 
			{
                temp.right = new BinaryTreeNode(key);
                break;
            }
            else
                q.add(temp.right);
        }
    }
	public List<List<Integer>> zigzagLevelOrder(BinaryTreeNode root) 
	{
        List<List<Integer>> list = new LinkedList<>();
        if(root == null) return list;
        Queue<BinaryTreeNode> q = new LinkedList<>();
        q.offer(root);
        boolean reverse = false;
        while(!q.isEmpty())
		{
            int n = q.size();
            List<Integer> l = new LinkedList<>();
            for(int i=0;i<n;i++){
                BinaryTreeNode curr = q.poll();
                l.add(curr.data);
                if(curr.left!=null&&curr.left.data!=-1) 
					q.offer(curr.left);
                if(curr.right!=null&&curr.right.data!=-1) 
					q.offer(curr.right);
            }
            if (reverse) 
			{
                Collections.reverse(l);
            }
            list.add(l);
            reverse = !reverse;
        }
        return list;
    }
	public static void main(String[] args) 
	{
		Scanner sc=new Scanner(System.in);
		String str[]=sc.nextLine().split(" ");
		ZigZagOrder st=new ZigZagOrder();
		root=new BinaryTreeNode(Integer.parseInt(str[0]));
		for(int i=1; i<str.length; i++)
			st.insert(root,Integer.parseInt(str[i]));
		System.out.println(st.zigzagLevelOrder(root));	
	}
}

/*
678. Valid Parenthesis String
Given a string s containing only three types of characters: '(', ')' and '*', 
return true if s is valid.

The following rules define a valid string:

Any left parenthesis '(' must have a corresponding right parenthesis ')'.
Any right parenthesis ')' must have a corresponding left parenthesis '('.
Left parenthesis '(' must go before the corresponding right parenthesis ')'.
'*' could be treated as a single right parenthesis ')' or a single left 
parenthesis '(' or an empty string "".

Example 1:
Input: s = "()"
Output: true

Example 2:
Input: s = "(*)"
Output: true

Example 3:
Input: s = "(*))"
Output: true
*/
import java.util.*;
class ValidParenString
{
	public static boolean checkValidString(String s) 
	{
        int leftMin = 0, leftMax = 0;

        for (char c : s.toCharArray()) 
		{
            if (c == '(') 
			{
                leftMin++;
                leftMax++;
            } 
			else if (c == ')') 
			{
                leftMin--;
                leftMax--;
            } 
			else 
			{
                leftMin--;
                leftMax++;
            }
            if (leftMax < 0) 
				return false;
            if (leftMin < 0) 
				leftMin = 0;
        }

        return leftMin == 0;
    }
	public static void main(String[] args) 
	{
		Scanner sc=new Scanner(System.in);
		String s=sc.next();
		System.out.println(checkValidString(s));
	}
}

